import {surveySupport,interpolate} from './well-derived.js';
import {api,session,API_ORIGIN} from './auth.js';
import * as repository from './project-repository.js';
import {MIN_TRACK_WIDTH,MAX_TRACK_WIDTH,DEFAULT_TRACK_WIDTH,ensureBoard,activeBook,freshBook,addWell,addCurve,numericColumns,indexColumn,selectedObjects,rangeOf,curvePath,axisFor,depthFactor,palette,uid,finite,applyTemplate} from './well-canvas-model.js';

let ctx,key='',generation=0,loadingCount=0,search='',contextTarget=null,queue=[],outsideBound=false;
let renderEpoch=0;const ghostChecks=new WeakMap(),ghostDepthContexts=new WeakMap(),extentChecks=new WeakMap(),fitChecks=new WeakMap();
const cache=new Map(),failures=new Map(),pending=new Map(),undo=new Map(),redo=new Map();
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const board=()=>ensureBoard(ctx.state()),book=()=>activeBook(board()),data=()=>ctx.datasets();
const ds=id=>data().find(d=>d.id===id),col=(dataset,id)=>dataset?.columns?.find(c=>c.id===id),icon=id=>ctx.host.icon(id);
const fail=e=>ctx.host.toast(e.message||String(e));
const sourceUnit=c=>c?.effectiveUnit||c?.unit||'';
function normalizeScope(){const next=session.user?.uid+':'+ctx.project()?.id;if(key!==next){key=next;generation++;cache.clear();failures.clear();pending.clear();queue=[];loadingCount=0;search='';contextTarget=null;undo.clear();redo.clear();}}
export function configureWellCanvas(context){ctx=context;}
export function openCanvasAction(name){return action(name);}
export function loadWellDataset(dataset){return load(dataset);}
export function focusCanvasWell(id){
 const b=book(),current=b.wells.find(w=>w.wellId===id);
 if(current&&current.visible!==false&&b.selected?.wellId===current.id){
  if(board().focus!=='logs'){board().focus='logs';ctx.host.save();redraw();}
  return;
 }
 change('Focus well',()=>{
  const well=current||addWell(b,id,logDatasets());
  well.visible=true;
  well.name=ctx.host.getState().wellDrafts?.find(w=>w.id===id)?.name||well.name;
  if(b.selected?.wellId!==well.id){b.selected={wellId:well.id};b.selectionRange=null;b.brush=null;}
  board().focus='logs';
 });
}
export function focusCanvasInterval(id,top,base,reference){
 if(!id||!Number.isFinite(top)||!Number.isFinite(base)||top>=base)return;
 focusCanvasWell(id);
 const b=book(),well=b.wells.find(w=>w.wellId===id);
 if(!well)return;
 const basis=well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(data().find(d=>d.well===id&&indexColumn(d)));
 if(basis!==reference){ctx.host.toast('Switch the well canvas to '+reference+' to view this summary interval.');return;}
 const offset=well.linked===false?0:offsetFor(well);
 if(well.linked===false)well.range=[top,base];else b.range=[top-offset,base-offset];
 ctx.host.save();redraw();
}
export function wellComparisonView(analysis=''){
 const s=board(),original=s.activeBook,first=s.comparePrimary||original,second=s.compareBook;
 if(!second||second===first||!s.books.some(b=>b.id===second)||!s.books.some(b=>b.id===first))return wellCanvasView(analysis);
 let main,comparison;
 try{s.activeBook=first;main=wellCanvasView(original===first?analysis:'');s.activeBook=second;comparison=wellCanvasView(original===second?analysis:'').replaceAll('id="iw-canvas"','data-comparison-canvas').replaceAll('id="wb-range"','data-comparison-range').replaceAll('id="wb-cursor-readout"','data-comparison-readout');}finally{s.activeBook=original;}
 return `<div class="pp-comparison"><div data-wb-pane="${first}">${main}</div><div data-wb-pane="${second}">${comparison}</div></div>`;
}
export function canvasContext(){const b=book(),s=selectedObjects(b),curve=s.curve||s.track?.curves[0]||s.well?.tracks.flatMap(t=>t.curves)[0],dataset=ds(curve?.datasetId);if(!dataset)return null;if(dataset.isProposal)throw new Error('Review and accept this proposed result before using it as a downstream calculation input.');const index=col(dataset,curve.indexColumnId)||indexColumn(dataset);return {dataset,curve,well:s.well,scope:index&&depthFactor(sourceUnit(index))?{datasetId:dataset.id,columnId:index.id,unit:sourceUnit(index),reference:dataset.references?.depthReference||'Unconfirmed',...(b.selectionRange?{top:sourceDepth(s.well,dataset,b.selectionRange.top)/depthFactor(sourceUnit(index)),base:sourceDepth(s.well,dataset,b.selectionRange.base)/depthFactor(sourceUnit(index))}:{}),...(b.brush?.datasetId===dataset.id?{rowRanges:brushRanges(b.brush)}:{})}:null};}
function rememberScroll(){for(const el of document.querySelectorAll('.wb-board-scroll')){const id=el.closest('[data-wb-pane]')?.dataset.wbPane||board().activeBook,target=board().books.find(b=>b.id===id);if(target)target.scroll={left:el.scrollLeft,top:el.scrollTop};}}
function snapshot(){return JSON.stringify({...board(),__zones:ctx.state().zones||[]});}
function restoreSnapshot(text){const value=JSON.parse(text);if(Object.hasOwn(value,'__zones')){ctx.state().zones=value.__zones;delete value.__zones;}ctx.state().board=value;}
function change(label,fn){rememberScroll();const b=board(),before=snapshot(),history=undo.get(key)||[];history.push({label,state:before});if(history.length>30)history.shift();undo.set(key,history);const previousRedo=redo.get(key);redo.set(key,[]);try{fn();}catch(error){restoreSnapshot(before);history.pop();redo.set(key,previousRedo||[]);throw error;}ctx.host.save();ctx.host.render();}
function redraw(){if(document.querySelector('.iw'))ctx.host.render();}
function select(well,track=null,curve=null){book().selected={wellId:well.id,trackId:track?.id,curveId:curve?.id};board().focus='logs';ctx.state().inspector=true;ctx.host.save();redraw();}
function allWells(){const names=new Set((ctx.host.getState().wellDrafts||[]).map(w=>w.id));for(const d of data())if(d.well)names.add(d.well);return [...names];}
function logDatasets(){return data().filter(d=>(d.family==='logs'||d.family==='derived'&&indexColumn(d))&&numericColumns(d).some(c=>c.id!==indexColumn(d)?.id));}

async function readDataset(dataset){
 if(dataset.rowCount>250000||(dataset.rowCount||0)*(dataset.columns?.length||0)>12000000)throw new Error('This display supports up to 250,000 rows / 12 million scalar cells per dataset. Prepare a bounded dataset; no samples have been silently omitted.');
 const visible=new Set(board().books.filter(b=>b.id===board().activeBook||b.id===board().compareBook||b.id===board().comparePrimary).flatMap(b=>b.wells.flatMap(w=>w.tracks.flatMap(t=>t.curves.map(c=>c.datasetId)))));for(const [id] of cache)if(!visible.has(id)&&id!==dataset.id)cache.delete(id);
 if([...cache.values()].reduce((n,d)=>n+d.rowCount*d.columns.length,0)+(dataset.rowCount||0)*(dataset.columns?.length||0)>12000000)throw new Error('These visible datasets exceed the 12-million-cell display budget. Remove unused well displays or use a separate workbook.');
 let rows=[],columns=dataset.columns||[],metadata={},references=dataset.references||{};
 const p=ctx.project();
 if(p.storage==='cloud'&&dataset.isProposal){
  for(const chunk of dataset.chunks||[]){const response=await fetch(API_ORIGIN+`/api/projects/${encodeURIComponent(p.id)}/science/runs/${encodeURIComponent(dataset.scientificRunId)}/artifacts/${encodeURIComponent(chunk.name)}`,{headers:{Authorization:'Bearer '+await session.user.getIdToken()}});if(!response.ok)throw new Error('The proposed result chunk could not be opened.');const blob=await response.blob();if(blob.size>8*1024**2)throw new Error('The proposal chunk exceeds the reader budget.');const text=await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text();if(text.length>64*1024**2)throw new Error('The expanded proposal chunk exceeds the reader budget.');for(const line of text.split('\n'))if(line.trim())rows.push(JSON.parse(line));}
 }else if(p.storage==='cloud'){
  for(let start=0;start<dataset.rowCount;start+=5000){const page=await api(`/api/projects/${p.id}/science/datasets/${dataset.id}/rows?start=${start}&limit=5000`);if(!page.rows.length)throw new Error('The stored row index ended before the dataset manifest. Refresh or inspect the source.');rows.push(...page.rows);columns=page.columns;metadata=page.metadata;references=page.references||references;}
 }else{
  const full=ctx.host.getState().ingestion?.imports?.find(i=>i.id===dataset.importId)?.datasets?.find(d=>d.id===dataset.id)||dataset;
  metadata=full.metadata||{};columns=full.columns;references=full.references||references;
  for(const chunk of full.chunks||[]){const blob=await repository.getArtifact(p,dataset.importId,chunk.name);if(blob.size>16*1024**2)throw new Error('This local chunk exceeds the bounded display reader.');const text=chunk.name.endsWith('.gz')?await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text():await blob.text();if(text.length>64*1024**2)throw new Error('The expanded chunk exceeds the display memory budget.');for(const line of text.split('\n'))if(line.trim())rows.push(JSON.parse(line));}
 }
 if(rows.length!==dataset.rowCount)throw new Error('Stored samples do not match the dataset row count. No partial display has been marked complete.');
 return {rows,columns,metadata,references,rowCount:rows.length};
}
function restoreLegacyRange(){const s=board(),b=book(),visible=b.wells.filter(w=>w.tracks.some(t=>t.curves.length));if(s.rangeSafetyVersion||!visible.length||visible.some(w=>w.tracks.some(t=>t.curves.some(c=>!cache.has(c.datasetId)))))return;const extents=visible.map(w=>{const e=wellExtent(w),r=visibleRange(w),o=offsetFor(w);return e?{e:[e[0]-o,e[1]-o],r}:null;}).filter(Boolean);if(extents.length&&extents.every(({e,r})=>r[1]<e[0]||r[0]>e[1])){b.range=null;for(const w of visible)w.range=null;ctx.host.toast('Restored the displayed depth range to your loaded logs.');}s.rangeSafetyVersion=1;ctx.host.save();}
function pump(){while(loadingCount<2&&queue.length){const task=queue.shift(),g=generation;loadingCount++;readDataset(task.dataset).then(value=>{if(g===generation){cache.set(task.dataset.id,value);restoreLegacyRange();task.resolve(value);}}).catch(e=>{if(g===generation)failures.set(task.dataset.id,e.message);task.reject(e);}).finally(()=>{if(g===generation){loadingCount--;pending.delete(task.dataset.id);pump();redraw();}});}}
function load(dataset){if(!dataset)return Promise.reject(new Error('The source dataset is no longer active.'));if(cache.has(dataset.id))return Promise.resolve(cache.get(dataset.id));if(pending.has(dataset.id))return pending.get(dataset.id);const promise=new Promise((resolve,reject)=>queue.push({dataset,resolve,reject}));pending.set(dataset.id,promise);pump();return promise;}
function want(dataset){if(dataset&&!cache.has(dataset.id)&&!pending.has(dataset.id)&&!failures.has(dataset.id))queueMicrotask(()=>load(dataset).catch(()=>{}));}
function support(well){return surveySupport(ctx.host,well.wellId,data(),redraw);}
function sourceBasis(dataset){return dataset?.references?.depthReference||'Unconfirmed';}
function elevation(well){const record=ctx.host.getState().wellDrafts?.find(w=>w.id===well.wellId),factor=depthFactor(record?.elevationUnit);return record?.elevationDatum==='MSL'&&factor&&finite(record.elevation)?record.elevation*factor:null;}
function convertDepth(well,value,from,to){if(!finite(value))return null;if(!to||to==='Source reference'||from===to)return value;const stations=support(well)?.stations||[];let tvd=from==='MD'?interpolate(stations,'md','tvd',value):from==='TVDSS'&&elevation(well)!==null?value+elevation(well):from==='TVD'?value:null;if(tvd===null)return null;return to==='TVD'?tvd:to==='TVDSS'&&elevation(well)!==null?tvd-elevation(well):to==='MD'?interpolate(stations,'tvd','md',tvd):null;}
function sourceDepth(well,dataset,z){const result=convertDepth(well,z,!well?.basis||well.basis==='Source reference'?sourceBasis(dataset):well.basis,sourceBasis(dataset));if(!finite(result))throw new Error('The selected interval cannot be converted to the retained source reference.');return result;}
function shownDepth(well,dataset,value){if(well.basis&&well.basis!=='Source reference'&&well.basis!==sourceBasis(dataset)&&(!dataset.references?.verticalDatum||dataset.references.verticalDatum!==support(well)?.references.verticalDatum))return null;return convertDepth(well,value,sourceBasis(dataset),well.basis);}
function ghostStatus(curve){if(!curve.ghostTransform)return '';const cached=ghostChecks.get(curve);if(cached?.epoch===renderEpoch)return cached.status;const transform=curve.ghostTransform;let status='';for(const v of transform.sourceVersions||[]){const current=ds(v.datasetId),index=indexColumn(current);if(!current||current.sourceSha256!==v.sourceSha256||sourceUnit(index)!==v.indexUnit||sourceBasis(current)!==v.depthReference){status='Ghost source changed; review overlay';break;}}if(!status&&transform.anchors?.length){const markers=markerCatalog();for(const a of transform.anchors){const source=markers.find(m=>m.id===a.sourceMarkerId),target=markers.find(m=>m.id===a.targetMarkerId);if(!source||!target||source.depth!==a.sourceEvidenceDepth||target.depth!==a.targetEvidenceDepth||source.reference!==a.sourceEvidenceReference||target.reference!==a.targetEvidenceReference||source.name!==a.sourceEvidenceName||target.name!==a.targetEvidenceName){status='Ghost anchors changed; review overlay';break;}}}ghostChecks.set(curve,{epoch:renderEpoch,status});return status;}
function displayDepth(well,dataset,value,curve){
 if(!curve?.ghostSourceWell)return shownDepth(well,dataset,value);
 if(ghostStatus(curve))return null;
 let context=ghostDepthContexts.get(curve);if(context?.epoch!==renderEpoch){const targetSource=data().find(d=>d.well===well.wellId&&indexColumn(d)),basis=well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(targetSource),original=book().wells.find(w=>w.wellId===curve.ghostSourceWell)||{wellId:curve.ghostSourceWell};context={epoch:renderEpoch,basis,source:{...original,basis}};ghostDepthContexts.set(curve,context);}const {basis,source}=context,z=shownDepth(source,dataset,value),transform=curve.ghostTransform;
 if(!finite(z))return null;if(!transform?.anchors?.length)return z;if(transform.reference!==basis)return null;
 const anchors=transform.anchors;if(anchors.length===1)return z+anchors[0].target-anchors[0].source;
 if(z<anchors[0].source||z>anchors.at(-1).source)return null;
 for(let i=1;i<anchors.length;i++)if(z<=anchors[i].source){const a=anchors[i-1],b=anchors[i];return a.target+(z-a.source)/(b.source-a.source)*(b.target-a.target);}return null;
}
function domainOptions(well){const source=data().find(d=>d.family==='logs'&&d.well===well.wellId),base=sourceBasis(source),result=['Source reference'];if(['MD','TVD','TVDSS'].includes(base))result.push(base);const currentSupport=support(well),stations=currentSupport?.stations,compatible=source?.references?.verticalDatum&&source.references.verticalDatum===currentSupport?.references.verticalDatum;if(compatible&&stations?.length>=2&&stations.every((p,i)=>finite(p.md)&&finite(p.tvd)&&(!i||p.md>stations[i-1].md))){result.push('TVD');if(stations.every((p,i)=>finite(p.tvd)&&(!i||p.tvd>stations[i-1].tvd)))result.push('MD');if(elevation(well)!==null)result.push('TVDSS');}return [...new Set(result)];}
function markerCatalog(){return [...book().markers.map(m=>({...m,markerId:m.markerId||ctx.host.getState().stratigraphy?.markers.find(s=>s.name.toLowerCase()===m.name.toLowerCase())?.id})),...(ctx.host.getState().stratigraphy?.picks||[]).map(p=>({...p,name:ctx.host.getState().stratigraphy.markers.find(m=>m.id===p.markerId)?.name||p.name,imported:true}))];}
function shownMarkers(well,includeHidden=false){return markerCatalog().filter(m=>m.wellId===well.wellId&&(includeHidden||!book().hiddenMarkers?.includes(m.markerId||m.id))).map(m=>({...m,depth:convertDepth(well,m.depth,m.reference==='Source reference'?sourceBasis(data().find(d=>d.family==='logs'&&d.well===well.wellId)):m.reference||'Unconfirmed',well.basis==='Source reference'||!well.basis?sourceBasis(data().find(d=>d.family==='logs'&&d.well===well.wellId)):well.basis)})).filter(m=>finite(m.depth));}
function curveViews(datasetId,columnId){return book().wells.flatMap(w=>w.tracks.flatMap(t=>t.curves.filter(c=>c.datasetId===datasetId&&(!columnId||c.columnId===columnId))));}
function toggleCurves(dataset,columns,checked){let well=book().wells.find(w=>w.wellId===dataset.well);if(checked&&!well){well=addWell(book(),dataset.well,[]);well.name=ctx.host.getState().wellDrafts?.find(w=>w.id===dataset.well)?.name||dataset.well;}if(!well)return;for(const column of columns){const matches=curveViews(dataset.id,column.id);if(checked&&!matches.length)addCurve(well,dataset,column.id);else matches.forEach(c=>c.visible=checked);}if(checked)well.visible=true;}
function wellExtent(well){const previous=extentChecks.get(well);if(previous?.epoch===renderEpoch)return previous.value;const values=[];for(const track of well.tracks)for(const c of track.curves){const source=cache.get(c.datasetId),dataset=ds(c.datasetId);if(!source||c.visible===false)continue;const index=source.columns.findIndex(v=>v.id===(c.indexColumnId||indexColumn(dataset)?.id)),factor=depthFactor(sourceUnit(source.columns[index]));if(index<0||!factor)continue;const ext=rangeOf(source.rows.map(r=>finite(r[index])?displayDepth(well,dataset,r[index]*factor,c):null));if(ext)values.push(...ext);}const value=rangeOf(values);extentChecks.set(well,{epoch:renderEpoch,value});return value;}
function fitRange(){const current=book(),previous=fitChecks.get(current);if(previous?.epoch===renderEpoch)return previous.value;const ranges=current.wells.filter(w=>w.visible!==false).flatMap(w=>{const r=wellExtent(w),offset=offsetFor(w);return r?[r[0]-offset,r[1]-offset]:[];});const value=rangeOf(ranges)||[0,1];fitChecks.set(current,{epoch:renderEpoch,value});return value;}
function offsetFor(well){if(book().flatten){const marker=shownMarkers(well,true).find(m=>m.name===book().flatten);if(marker)return marker.depth;}return Number(well.offset||0);}
function visibleRange(well){const b=book();return well.linked===false?well.range||wellExtent(well)||[0,1]:b.range||fitRange();}

export function wellBrowserView(){normalizeScope();const query=search.toLowerCase(),b=book(),registry=ctx.host.getState().wellDrafts||[],checkbox=(kind,id,on,partial=false)=>`<input type="checkbox" data-wb-visibility="${kind}" data-id="${esc(id)}" ${on?'checked':''} data-partial="${partial}" aria-label="Show ${esc(id)}">`;
 const curvesFor=d=>numericColumns(d).filter(c=>c.id!==indexColumn(d)?.id),shown=(d,c)=>b.wells.some(w=>w.wellId===d.well&&w.visible!==false)&&curveViews(d.id,c?.id).some(v=>v.visible!==false);
 const tree=allWells().map(id=>{const well=b.wells.find(w=>w.wellId===id),record=registry.find(w=>w.id===id),sources=logDatasets().filter(d=>d.well===id),evidence=data().filter(d=>(d.well===id||d.wellRecords?.some(record=>record.id===id))&&!sources.some(s=>s.id===d.id)),curves=sources.flatMap(d=>curvesFor(d).map(c=>({d,c}))),count=curves.filter(({d,c})=>shown(d,c)).length;
  if(query&&!(record?.name+' '+id+' '+sources.map(d=>d.name+' '+d.columns.map(c=>c.mnemonic).join(' ')).join(' ')).toLowerCase().includes(query))return '';
  return `<details data-wb-tree-well="${esc(id)}" data-wb-tree-key="well:${esc(id)}" ${query||board().treeOpen?.includes('well:'+id)?'open':''}><summary>${checkbox('well',id,!!well&&well.visible!==false,count>0&&count<curves.length)}<strong draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'well',wellId:id}))}'>${esc(record?.name||id)}</strong><button data-wb-open-well="${esc(id)}" aria-label="Add well to canvas">${icon('plus')}</button></summary><small>${esc(record?.uwi||'UWI unresolved')}</small><button data-wb-import-well="${esc(id)}">Import well evidenceâ€¦</button>${sources.map(d=>{const columns=curvesFor(d),visible=columns.filter(c=>shown(d,c)).length;return `<details class="wb-run" data-wb-tree-key="run:${esc(d.id)}" ${query||board().treeOpen?.includes('run:'+d.id)?'open':''}><summary>${checkbox('run',d.id,visible===columns.length&&visible>0,visible>0&&visible<columns.length)}<span>${esc(d.name)}<small>${d.rowCount.toLocaleString()} samples Â· log run</small></span></summary>${columns.map(c=>`<div class="wb-tree-curve">${checkbox('curve',d.id+':'+c.id,shown(d,c))}<button draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'curve',wellId:id,datasetId:d.id,columnId:c.id}))}' data-wb-add-curve="${esc(d.id)}:${esc(c.id)}" data-wb-context='${esc(JSON.stringify({kind:'source',datasetId:d.id,columnId:c.id,wellId:id}))}'>âˆ¿ ${esc(c.mnemonic)}<small>${esc(c.propertyType||'Unclassified')} Â· ${esc(sourceUnit(c)||'unit unresolved')}</small></button></div>`).join('')}</details>`;}).join('')}${evidence.map(d=>`<button data-wb-inspect="${esc(d.id)}">${esc(d.family)} Â· ${esc(d.name)}${record?.activeSurveyId===d.id||record?.activeCheckshotId===d.id?' Â· active':''}</button>`).join('')}${!sources.length?'<p class="wb-muted">No log run retained.</p>':''}</details>`;
 }).join('');
 const types=[...new Set(logDatasets().flatMap(d=>curvesFor(d).map(c=>c.propertyType||'Unclassified')))];
 return `<aside class="iw-browser wb-browser" aria-label="Well evidence and visibility"><header><strong>Project evidence</strong><button class="iw-icon" id="iw-browser-close" aria-label="Collapse project browser">${icon('close')}</button></header><label class="iw-search"><input id="wb-search" placeholder="Find well, run or curveâ€¦" aria-label="Find evidence" value="${esc(search)}"></label><div class="wb-tree-actions"><button data-wb-action="register">${icon('plus')}Add well</button><button data-wb-action="import">${icon('upload')}Import</button></div><div class="wb-tree">${tree||'<p class="wb-muted">Import well evidence to start.</p>'}<details><summary>Global curve categories</summary>${types.map(type=>{const entries=logDatasets().flatMap(d=>curvesFor(d).filter(c=>(c.propertyType||'Unclassified')===type).map(c=>({d,c}))),count=entries.filter(({d,c})=>shown(d,c)).length;return `<label>${checkbox('type',type,count===entries.length,count>0&&count<entries.length)}${esc(type)} Â· ${entries.length}</label>`;}).join('')}</details><details><summary>Shared stratigraphy</summary>${[...new Map(markerCatalog().map(m=>[m.markerId||m.id,m])).values()].map(m=>`<label>${checkbox('marker',m.markerId||m.id,!b.hiddenMarkers?.includes(m.markerId||m.id))}${esc(m.name)}</label>`).join('')||'<p>No imported or picked markers.</p>'}</details><details><summary>Unassigned evidence</summary>${data().filter(d=>!d.well&&!d.wellRecords?.length).map(d=>`<button data-wb-inspect="${esc(d.id)}">${esc(d.name)}</button>`).join('')}</details></div><footer class="wb-tree-footer">Visibility is saved in this workbook. Hidden curves remain imported and retain their styles.</footer></aside>`;
}

export function wellCanvasView(analysis=''){
 renderEpoch++;normalizeScope();const s=board(),b=book();
 if(!s.migrated){const legacy=ctx.state().windows.filter(w=>w.tool==='logs'&&w.datasetId);if(!legacy.length||legacy.every(w=>ds(w.datasetId))){for(const old of legacy){const dataset=ds(old.datasetId);if(!dataset)continue;const well=addWell(b,dataset.well||'Unassigned evidence',[]);for(const id of old.curves||numericColumns(dataset).filter(c=>c.id!==indexColumn(dataset)?.id).slice(0,3).map(c=>c.id)){const track=addCurve(well,dataset,id),curve=track.curves[0];Object.assign(curve,old.axes?.[id]||{});}if(old.depthColumn)for(const t of well.tracks)for(const c of t.curves)c.indexColumnId=old.depthColumn;old.closed=true;}s.migrated=true;ctx.host.save();}}
 if(!s.initialLogDisplayPrepared&&logDatasets().length&&s.books.length===1&&!s.books.some(w=>w.wells.length)){for(const id of [...new Set(logDatasets().map(d=>d.well).filter(Boolean))].slice(0,30)){const well=addWell(b,id,logDatasets());well.name=ctx.host.getState().wellDrafts?.find(w=>w.id===id)?.name||well.name;}s.initialLogDisplayPrepared=true;ctx.host.save();}
 if(b.wells.length)s.initialLogDisplayPrepared=true;
 for(const well of b.wells)for(const track of well.tracks)for(const curve of track.curves)want(ds(curve.datasetId));
 const domains=[...new Set(b.wells.filter(w=>w.visible!==false).flatMap(w=>w.tracks.flatMap(t=>t.curves.filter(c=>c.visible!==false).map(c=>w.basis&&w.basis!=='Source reference'?w.basis:sourceBasis(ds(c.datasetId))))))];const selected=selectedObjects(b),range=b.range||fitRange(),outside=b.wells.some(w=>{const e=wellExtent(w),r=visibleRange(w),o=offsetFor(w);return e&&(r[1]<e[0]-o||r[0]>e[1]-o);});
 return `<div class="wb-studio ${ctx.state().grid===false?'wb-grid-off':''}" id="iw-canvas"><nav class="wb-workbooks" aria-label="Interpretation workbooks">${s.books.map(w=>`<button data-wb-book="${w.id}" aria-current="${w.id===s.activeBook?'page':'false'}">${icon('file')}${esc(w.name)}</button>`).join('')}<button class="iw-icon" data-wb-action="new-book" title="New workbook" aria-label="New workbook">${icon('plus')}</button><button class="iw-icon" data-wb-action="manage-book" title="Rename or close workbook" aria-label="Manage workbook">${icon('settings')}</button></nav>
 <div class="wb-controls"><div><button data-wb-action="undo" title="Undo display edit" aria-label="Undo" ${!(undo.get(key)?.length)?'disabled':''}>â†¶</button><button data-wb-action="redo" title="Redo display edit" aria-label="Redo" ${!(redo.get(key)?.length)?'disabled':''}>â†·</button><button data-wb-action="zoom-in" aria-label="Zoom depth in" title="Zoom in">${icon('plus')}</button><button data-wb-action="zoom-out" aria-label="Zoom depth out" title="Zoom out">âˆ’</button><button data-wb-action="fit">Fit depth</button></div><div><button data-wb-action="all-wells">Add wellsâ€¦</button><button data-wb-action="empty-track">Add track</button><button data-wb-action="tops">${b.pickTop?'Cancel top pick':'Pick top'}</button><button data-wb-action="crossplot">Crossplot</button><button data-wb-action="templates">Templates</button><button data-wb-action="recipes">Recipes</button><button data-wb-action="versions">History</button><button data-wb-action="export">Export</button></div></div>
 <div class="wb-depth-bar"><form id="wb-range"><label>Top <input name="top" type="number" step="any" aria-label="Canvas top depth in metres" value="${Number(range[0].toFixed(3))}"></label><label>Base <input name="base" type="number" step="any" aria-label="Canvas base depth in metres" value="${Number(range[1].toFixed(3))}"></label><button title="Apply depth range">Apply</button></form><span>m Â· ${esc(selected.well?.basis||'source reference retained')}</span><button data-wb-action="link" aria-pressed="${b.linked}">${b.linked?'Linked depths':'Independent depths'}</button><button data-wb-action="correlate" aria-pressed="${b.correlation}">${b.correlation?'Correlation on':'Correlate tops'}</button><button data-wb-action="flatten">${b.flatten?'Flattened: '+esc(b.flatten):'Flatten on topâ€¦'}</button>${b.selectionRange||b.brush?'<button data-wb-action="clear-selection">Clear interval / brush</button>':''}</div>
 ${(ctx.state().proposals||[]).length?`<div class="wb-proposal-bar">Proposed / reviewed comparisons Â· originals unchanged ${[...new Set(ctx.state().proposals.filter(d=>d.status.startsWith('Proposed')&&d.reviewable!==false).map(d=>d.scientificRunId))].map(id=>`<button data-wb-review-run="${esc(id)}">Review calculated version</button>`).join("")}</div>`:""}${domains.length>1?'<p class="note">Different source depth domains are displayed. Confirm compatible references before correlating wells or interpreting linked depths.</p>':''}${outside?`<div class="wb-range-warning" role="status">The displayed depth range is outside the loaded logs.<button data-wb-action="fit">Fit depth to logs</button></div>`:""}<div class="wb-board-scroll"><div class="wb-board ${b.pickTop?'wb-picking':''}" data-wb-drop="board">${b.wells.length?b.wells.filter(w=>w.visible!==false).map(wellView).join(''):`<div class="wb-empty"><span>${icon('logs')}</span><h2>Build your well-log canvas</h2><p>Drag a well from the tree, then drop curves into its tracks. Compare wells, pick tops and calculate from the selected evidence.</p><button class="primary" data-wb-action="all-wells">Choose wells to display</button><small>No curves, wells or results are generated for this empty canvas.</small></div>`}<div class="wb-drop-well" data-wb-drop="board">${icon('plus')}Drop a well here</div>${b.correlation?correlationLines():''}</div></div>
 ${b.crossplot?crossplotView():''}${s.focus==='analysis'&&analysis?`<section class="wb-analysis"><header><strong>Analysis Â· linked to canvas selection</strong><button data-wb-action="back-to-logs">Return to log properties ${icon('close')}</button></header>${analysis}</section>`:''}
 <footer class="wb-status"><span>${b.wells.length} wells Â· ${b.wells.reduce((n,w)=>n+w.tracks.length,0)} tracks Â· ${b.wells.some(w=>w.tracks.some(t=>t.curves.some(c=>!cache.has(c.datasetId)&&!failures.has(c.datasetId))))?'Loading full stored samplesâ€¦':failures.size?'Review source loading errors':'Complete stored samples loaded'}</span><span id="wb-cursor-readout">${s.cursor?esc(s.cursor):'Click for values Â· Ctrl+wheel zoom Â· Shift+wheel pan Â· Shift-drag select'}</span></footer></div>`;
}
function rulerWidth(well){return 44*(1+(well.rulers?.length||0));}
function referenceRulers(well,range,offset){const source=data().find(d=>d.well===well.wellId&&indexColumn(d)),basis=well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(source);return (well.rulers||[]).map((ref,i)=>ticks(range).map(v=>{const z=ref==='ft'?(v+offset)/.3048:convertDepth(well,v+offset,basis,ref);return `<text x="${49+i*44}" y="${(v-range[0])/(range[1]-range[0])*620+4}">${finite(z)?z.toFixed(range[1]-range[0]<20?2:0):'â€”'}</text>`;}).join('')).join('');}
function wellView(well){const b=book(),width=rulerWidth(well)+well.tracks.reduce((n,t)=>n+t.width,0)+20,range=visibleRange(well),offset=offsetFor(well),count=new Set(well.tracks.flatMap(t=>t.curves.map(c=>c.datasetId)));
 return `<section class="wb-well ${b.selected?.wellId===well.id?'wb-active-well':''}" data-wb-well="${well.id}" style="width:${Math.max(96,width)}px"><header class="wb-well-heading" draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'well-view',id:well.id}))}' data-wb-select='${esc(JSON.stringify({wellId:well.id}))}'><div><strong title="${esc(well.name)}">${esc(well.name)}</strong><small title="${esc(well.basis||'Source depth reference')}">${count.size} runs Â· ${esc(well.basis||'Source depth reference')} Â· ${well.linked===false?'independent':'linked'}</small></div><button data-wb-well-menu="${well.id}" aria-label="Manage ${esc(well.name)}">â‹¯</button></header><div class="wb-tracks" data-wb-drop="well" data-well-id="${well.id}"><div class="wb-depth-track" style="width:${rulerWidth(well)}px;flex-basis:${rulerWidth(well)}px"><header><strong>${esc(well.basis||'Index')}</strong><small>metres ${offset?'Â· flattened':''} ${esc((well.rulers||[]).join(' Â· '))}</small></header><svg viewBox="0 0 ${rulerWidth(well)} 620" class="wb-depth-svg" aria-label="Depth ruler">${ticks(range).map(v=>`<text x="5" y="${(v-range[0])/(range[1]-range[0])*620+4}">${v.toFixed(range[1]-range[0]<20?2:0)}</text>`).join('')}${referenceRulers(well,range,offset)}</svg></div>${well.tracks.map((t,i)=>trackView(well,t,i,range,offset)).join('')}<button class="wb-add-track" data-wb-new-track="${well.id}" data-wb-drop="well" data-well-id="${well.id}" aria-label="Add track to ${esc(well.name)}">${icon('plus')}</button></div><button class="wb-well-resize" data-wb-well-resize="${well.id}" aria-label="Resize ${esc(well.name)} well display" title="Drag to resize well; arrow keys adjust width" role="separator" aria-orientation="vertical"></button></section>`;
}
function ticks(range){return Array.from({length:11},(_,i)=>range[0]+(range[1]-range[0])*i/10);}
function trackView(well,track,i,range,offset){
 const selection=book().selected,isSelected=selection?.trackId===track.id,height=620;
 const paths=track.curves.filter(c=>c.visible).map(curve=>{const dataset=ds(curve.datasetId),source=cache.get(curve.datasetId);if(ghostStatus(curve))return `<text x="5" y="35" class="wb-error-label">${esc(ghostStatus(curve))}</text>`;if(!source)return failures.has(curve.datasetId)?`<text x="5" y="35" class="wb-error-label">Source unavailable</text>`:`<text x="5" y="35" class="wb-error-label">Loading samplesâ€¦</text>`;const ci=source.columns.findIndex(c=>c.id===curve.columnId),di=source.columns.findIndex(c=>c.id===(curve.indexColumnId||indexColumn(dataset)?.id)),factor=depthFactor(sourceUnit(source.columns[di]));if(!factor||di<0)return '<text x="5" y="35" class="wb-error-label">Confirm depth index/unit</text>';const axis=axisFor(source.rows,ci,curve);if(!axis)return '<text x="5" y="35" class="wb-error-label">No finite values in scale</text>';const path=curvePath(source.rows,di,ci,range,axis,track.width-12,height,offset,factor,z=>displayDepth(well,dataset,z,curve));const fill=curve.fill&&curve.fill!=='none'?path.split('M').filter(Boolean).map(segment=>{const values=segment.split('L'),first=values[0].split(',')[1],last=values.at(-1).split(',')[1],edge=curve.fill==='right'?track.width-12:0;return `<path d="M${edge},${first}L${segment}L${edge},${last}Z" fill="${esc(curve.color)}" opacity="${curve.fillOpacity??.12}"/>`;}).join(''):'';return `${!path?'<text x="8" y="44" class="wb-error-label">No samples in this interval</text>':''}<g transform="translate(6 0)">${fill}<path data-wb-curve-path="${curve.id}" d="${path}" stroke="${esc(curve.color)}" stroke-width="${isSelected&&selection.curveId===curve.id?1.8:1.15}" fill="none" ${curve.dashed?'stroke-dasharray="4 3"':''} vector-effect="non-scaling-stroke"/><text x="0" y="12" class="wb-axis-label" fill="${esc(curve.color)}">${axis.log?Math.pow(10,axis[0]).toPrecision(3):Number(axis[0].toPrecision(4))}</text><text x="${track.width-14}" y="12" text-anchor="end" class="wb-axis-label" fill="${esc(curve.color)}">${axis.log?Math.pow(10,axis[1]).toPrecision(3):Number(axis[1].toPrecision(4))}</text></g>`;}).join('');
 const bands=selectionBands(well,track,range,offset),tops=shownMarkers(well).map(m=>{const y=(m.depth-offset-range[0])/(range[1]-range[0])*height;return y<0||y>height?'':`<g class="wb-top"><line x1="0" x2="${track.width}" y1="${y}" y2="${y}" stroke="${esc(m.color||'#b78540')}" stroke-width="1.2"/><text x="5" y="${y-4}">${esc(m.name)}</text></g>`;}).join('');
 return `<div class="wb-track ${track.width<=60?'wb-slim-track':''} ${isSelected?'wb-active-track':''}" style="width:${track.width}px" data-wb-track="${track.id}" data-wb-drop="track" data-well-id="${well.id}" data-track-id="${track.id}" data-wb-context='${esc(JSON.stringify({kind:'track',wellId:well.id,trackId:track.id}))}'><header draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'track',wellId:well.id,trackId:track.id}))}'><button data-wb-select='${esc(JSON.stringify({wellId:well.id,trackId:track.id}))}'>${esc(track.name)}</button>${track.curves.map(c=>`<button title="${esc(c.name)} Â· ${esc(c.unit||'unit unresolved')}" class="wb-curve-chip ${selection?.curveId===c.id?'selected':''}" data-wb-select='${esc(JSON.stringify({wellId:well.id,trackId:track.id,curveId:c.id}))}' data-wb-context='${esc(JSON.stringify({kind:'curve',wellId:well.id,trackId:track.id,curveId:c.id}))}' style="color:${esc(c.color)}"><span>${c.visible?'âˆ¿':'â—‹'} ${esc(c.name)}</span><small>${esc(c.unit||'unit unresolved')}${c.dashed?' Â· overlay':''}${c.log?' Â· log':''}${ds(c.datasetId)?.scientificRunId?' Â· derived':''}</small></button>`).join('')}</header><svg class="wb-track-plot" data-wb-plot="${track.id}" data-well-id="${well.id}" viewBox="0 0 ${track.width} 620" preserveAspectRatio="none" tabindex="0" role="img" aria-label="${esc(well.name)} ${esc(track.name)} real log samples"><defs><clipPath id="clip-${track.id}"><rect width="${track.width}" height="620"/></clipPath></defs><rect width="${track.width}" height="620" fill="white"/>${Array.from({length:6},(_,j)=>`<line x1="${j*track.width/5}" x2="${j*track.width/5}" y1="0" y2="620" stroke="#eaf0ed"/>`).join('')}${ticks(range).map(d=>`<line x1="0" x2="${track.width}" y1="${(d-range[0])/(range[1]-range[0])*620}" y2="${(d-range[0])/(range[1]-range[0])*620}" stroke="#dce7e2"/>`).join('')}<g clip-path="url(#clip-${track.id})">${bands}${paths}${tops}</g><line class="wb-cursor-line" x1="0" x2="${track.width}" y1="-10" y2="-10" stroke="#294b45" stroke-dasharray="3 2"/></svg><footer>${track.curves.map(c=>{const p=cache.get(c.datasetId);return `<span>${p?p.rowCount.toLocaleString():'â€¦'} ${esc(c.name)}</span>`;}).join('')}</footer><button class="wb-track-resize" data-wb-track-resize="${well.id}:${track.id}" aria-label="Resize ${esc(track.name)} track" title="Drag to resize track; arrow keys adjust width" role="separator" aria-orientation="vertical"></button><button class="wb-insert-track" data-wb-insert="${well.id}:${i}" aria-label="Insert track before ${esc(track.name)}"></button></div>`;
}
function selectionBands(well,track,range,offset){const b=book(),intervals=[];if(b.selectionRange)intervals.push([b.selectionRange.top-offset,b.selectionRange.base-offset]);if(b.brush){const source=cache.get(b.brush.datasetId),dataset=ds(b.brush.datasetId),idx=source?.columns.findIndex(c=>c.id===indexColumn(dataset)?.id),factor=depthFactor(sourceUnit(source?.columns[idx]));if(source&&dataset.well===well.wellId&&factor){const selected=brushedIndices(b.brush);let first=null,last=null;for(const i of selected){const z=shownDepth(well,dataset,source.rows[i][idx]*factor)-offset;if(first===null)first=z;else if(i!==last+1){intervals.push([first,shownDepth(well,dataset,source.rows[last][idx]*factor)-offset]);first=z;}last=i;}if(first!==null)intervals.push([first,shownDepth(well,dataset,source.rows[last][idx]*factor)-offset]);}}
 const zoneBands=(ctx.state().zones||[]).filter(z=>z.wellId===well.wellId).map(z=>{const basis=well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(data().find(d=>d.well===well.wellId&&indexColumn(d))),top=convertDepth(well,z.top,z.reference,basis),base=convertDepth(well,z.base,z.reference,basis);if(!finite(top)||!finite(base))return '';const y=v=>(v-offset-range[0])/(range[1]-range[0])*620;return `<g class="wb-zone"><rect x="0" width="${track.width}" y="${y(top)}" height="${Math.max(0,y(base)-y(top))}" fill="#087c73" opacity=".04"/><text x="6" y="${y(top)+12}" font-size="9">${esc(z.name)}</text>${[['top',top],['base',base]].map(([edge,value])=>`<line x1="0" x2="${track.width}" y1="${y(value)}" y2="${y(value)}" stroke="#087c73" stroke-width="5" opacity=".35" data-wb-zone-boundary="${esc(z.id)}" data-edge="${edge}" tabindex="0" role="button" aria-label="Drag ${esc(z.name)} ${edge} boundary" style="cursor:ns-resize"/>`).join('')}</g>`;}).join('');
 return zoneBands+intervals.map(([top,base])=>`<rect x="0" y="${(top-range[0])/(range[1]-range[0])*620}" width="${track.width}" height="${Math.max(2,(base-top)/(range[1]-range[0])*620)}" fill="#d2a454" opacity=".18"/>`).join('');}
function correlationLines(){let left=0,previous=null,lines=[];for(const well of book().wells.filter(w=>w.visible!==false)){const width=Math.max(240,rulerWidth(well)+well.tracks.reduce((n,t)=>n+t.width,0)+34),range=visibleRange(well),offset=offsetFor(well),points=shownMarkers(well).map(m=>({name:m.markerId||m.name,reference:well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(data().find(d=>d.family==='logs'&&d.well===well.wellId)),y:128+(m.depth-offset-range[0])/(range[1]-range[0])*620}));if(previous)for(const p of points){const from=previous.points.find(v=>v.name===p.name&&v.reference===p.reference);if(from&&p.y>=128&&p.y<=748&&from.y>=128&&from.y<=748)lines.push(`<line x1="${previous.right}" x2="${left+rulerWidth(well)}" y1="${from.y}" y2="${p.y}" stroke="#b58c50" stroke-width="1" stroke-dasharray="4 3"/>`);}previous={points,right:left+width-34};left+=width+24;}return `<svg class="wb-correlations" width="${left}" height="780" aria-label="Lines connecting actual referenced well picks; not geological surfaces">${lines.join('')}</svg>`;}

export function wellInspectorView(){const {well,track,curve}=selectedObjects(book());
 if(!well)return `<aside class="iw-inspector wb-inspector"><header><strong>Canvas properties</strong><button class="iw-icon" id="iw-inspector-close" aria-label="Collapse properties">${icon('close')}</button></header><div class="iw-inspector-empty">Select a well, track or curve on the canvas. Drag wells and curves from the tree to build your display.</div></aside>`;
 const dataset=ds(curve?.datasetId),source=cache.get(curve?.datasetId),column=col(dataset,curve?.columnId);
 return `<aside class="iw-inspector wb-inspector"><header><strong>${curve?'Curve properties':track?'Track properties':'Well properties'}</strong><button class="iw-icon" id="iw-inspector-close" aria-label="Collapse properties">${icon('close')}</button></header><div class="wb-selection-summary"><strong>${esc(well.name)}</strong><span>${esc(track?.name||'Well display')}${curve?' / '+esc(curve.name):''}</span></div><form id="wb-properties"><label class="field">Display name<input name="name" required maxlength="120" value="${esc(curve?.name||track?.name||well.name)}"></label>${curve?`<label class="field">Line colour<input name="color" type="color" value="${esc(curve.color)}"></label><label class="iw-check"><input type="checkbox" name="visible" ${curve.visible?'checked':''}>Visible</label><label class="iw-check"><input type="checkbox" name="log" ${curve.log?'checked':''}>Logarithmic axis</label><label class="iw-check"><input type="checkbox" name="reverse" ${curve.reverse?'checked':''}>Reverse axis</label><label class="field">Fill<select name="fill">${['none','left','right'].map(v=>`<option ${curve.fill===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="iw-check"><input type="checkbox" name="dashed" ${curve.dashed?'checked':''}>Dashed / ghost overlay</label><div class="wb-two-fields"><label class="field">Axis minimum<input name="min" type="number" step="any" value="${curve.min??''}" placeholder="Auto"></label><label class="field">Axis maximum<input name="max" type="number" step="any" value="${curve.max??''}" placeholder="Auto"></label></div><label class="field">Depth/index column<select name="indexColumnId" required>${numericColumns(dataset||{}).map(c=>`<option value="${esc(c.id)}" ${c.id===curve.indexColumnId?'selected':''}>${esc(c.mnemonic)} Â· ${esc(sourceUnit(c)||'unit unresolved')}</option>`).join('')}</select></label>`:''}${track?`<label class="field">Track width (px)<input name="width" type="number" min="48" max="480" value="${track.width}"></label>`:''}<label class="field">Display depth reference<select name="basis">${domainOptions(well).map(v=>`<option ${well.basis===v?'selected':''}>${v}</option>`).join('')}</select><small>Available domains follow the active referenced survey. Derived depths interpolate between actual stations; source observations stay retained.</small></label><label class="iw-check"><input name="linked" type="checkbox" ${well.linked!==false?'checked':''}>Link depth navigation for this well</label><label class="field">Display depth offset (m)<input name="offset" type="number" step="any" value="${well.offset||0}"></label>${support(well)?.error?`<p class="note">Active survey: ${esc(support(well).error)}</p>`:''}<p id="wb-properties-error" role="alert"></p><button class="primary" type="submit">Apply display settings</button></form><div class="wb-inspector-actions">${track?'<button data-wb-action="duplicate-track">Duplicate track</button><button data-wb-action="remove-track">Remove track from view</button>':''}${curve?'<button data-wb-action="curve-export">Export curve CSV</button><button data-wb-action="provenance">Source & provenance</button><button data-wb-action="calculate">Calculate from selectionâ€¦</button><button data-wb-action="remove-curve">Remove curve from view</button>':''}<button data-wb-import-well="${esc(well.wellId)}">Add curves to this wellâ€¦</button></div>${curve?`<section class="wb-provenance"><h3>${dataset?.scientificRunId?'Calculated curve version':'Original source curve'}</h3><p>${esc(dataset?.name)} Â· ${esc(column?.mnemonic)} (${esc(column?.id)})</p><p>Source unit: ${esc(sourceUnit(column)||'Unresolved')} Â· ${source?source.rowCount.toLocaleString():'Loading'} retained samples</p><p>${dataset?.scientificRunId?'Derived result; activation does not grant scientific approval.':'Display edits never change original samples.'}</p>${failures.has(dataset?.id)?`<p role="alert">${esc(failures.get(dataset.id))}</p><button data-wb-retry="${esc(dataset.id)}">Retry source loading</button>`:''}</section>`:''}</aside>`;
}

function brandedForm(title,body,onSubmit){ctx.host.modal(title,`<form id="wb-dialog-form">${body}<p id="wb-dialog-error" role="alert"></p><button class="primary" type="submit">Save</button></form>`);$('#wb-dialog-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;button.title='Saving reviewed changes…';try{const form=e.target,result=onSubmit(new FormData(form));if(result&&typeof result.then==='function')await result;if($('#wb-dialog-form')===form)$('#dialog').close();redraw();}catch(error){$('#wb-dialog-error').textContent=error.message;button.disabled=false;}};}
function openWell(id){change('Add well display',()=>{const well=addWell(book(),id,logDatasets());well.name=ctx.host.getState().wellDrafts?.find(w=>w.id===id)?.name||well.name;well.visible=true;board().focus='logs';});}
function chooseWells(){ctx.host.modal('Add wells to canvas',`<p>Choose registered wells. This adds displays; it does not duplicate source files.</p><form id="wb-choose-wells">${allWells().map(id=>`<label class="iw-check"><input type="checkbox" name="well" value="${esc(id)}" ${book().wells.some(w=>w.wellId===id)?'checked':''}>${esc(id)}</label>`).join('')||'<p>No wells registered. Use Add well or import a LAS run.</p>'}<button class="primary">Add selected wells</button></form>`);$('#wb-choose-wells').onsubmit=e=>{e.preventDefault();const ids=new FormData(e.target).getAll('well');change('Add wells to canvas',()=>{for(const id of ids){const well=addWell(book(),id,logDatasets());well.name=ctx.host.getState().wellDrafts?.find(w=>w.id===id)?.name||well.name;}board().focus='logs';});$('#dialog').close();};}
function widthSettings(){const {well,track}=selectedObjects(book());brandedForm('Well and track widths',`<p>New tracks start at 48 px. Display widths do not resample or modify source curves.</p><label class="field">Apply to<select name="scope"><option value="all">All displayed wells</option>${well?'<option value="well">Selected well</option>':''}${track?'<option value="track">Selected track</option>':''}</select></label><label class="field">Width of each track (px)<input name="width" type="number" min="48" max="480" step="1" value="${track?.width||48}" required></label><p>Drag a track edge to adjust it independently. Drag a well edge to size its tracks together. Fit wells uses the available canvas width, with a 48 px minimum per track.</p>`,f=>{const width=Number(f.get('width'));if(!Number.isFinite(width)||width<MIN_TRACK_WIDTH||width>MAX_TRACK_WIDTH)throw new Error('Enter a track width from 48 to 480 pixels.');change('Set well display widths',()=>{const targets=f.get('scope')==='track'?[track]:f.get('scope')==='well'?well.tracks:book().wells.filter(w=>w.visible!==false).flatMap(w=>w.tracks);for(const t of targets)t.width=width;});});}
function setWellWidth(well,width){const n=well.tracks.length;if(!n)return;const each=Math.max(MIN_TRACK_WIDTH,Math.min(MAX_TRACK_WIDTH,Math.floor((width-rulerWidth(well)-20)/n)));for(const track of well.tracks)track.width=each;}
function fitWells(){const wells=book().wells.filter(w=>w.visible!==false),pane=document.querySelector('[data-wb-pane="'+book().id+'"] .wb-board-scroll')||document.querySelector('.wb-board-scroll');if(!wells.length||!pane)throw new Error('Add visible wells before fitting their widths.');const width=(pane.clientWidth-16-Math.max(0,wells.length-1)*12)/wells.length;change('Fit displayed well widths',()=>{for(const well of wells)setWellWidth(well,width);});if(wells.some(w=>w.tracks.some(t=>t.width===MIN_TRACK_WIDTH)))ctx.host.toast('Fitted to the minimum readable track width. Scroll horizontally for additional wells.');}
function bindWidthHandles(root){
 for(const handle of root.querySelectorAll('[data-wb-track-resize],[data-wb-well-resize]')){
  const ids=(handle.dataset.wbTrackResize||handle.dataset.wbWellResize).split(':'),well=book().wells.find(w=>w.id===ids[0]),track=well?.tracks.find(t=>t.id===ids[1]);if(!well)continue;
  const current=()=>track?track.width:rulerWidth(well)+well.tracks.reduce((n,t)=>n+t.width,0)+20;
  handle.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();change('Resize log display',()=>{const next=current()+(e.key==='ArrowRight'?8:-8);if(track)track.width=Math.max(MIN_TRACK_WIDTH,Math.min(MAX_TRACK_WIDTH,next));else setWellWidth(well,next);});};
  handle.onpointerdown=e=>{e.preventDefault();e.stopPropagation();const initial=current(),x=e.clientX,element=handle.closest('.wb-well'),trackElement=track?handle.closest('.wb-track'):null,startWell=element.offsetWidth;let proposed=initial;handle.setPointerCapture(e.pointerId);
   const move=event=>{proposed=Math.max(track?MIN_TRACK_WIDTH:rulerWidth(well)+well.tracks.length*MIN_TRACK_WIDTH+20,Math.min(track?MAX_TRACK_WIDTH:rulerWidth(well)+well.tracks.length*MAX_TRACK_WIDTH+20,initial+event.clientX-x));if(trackElement)trackElement.style.width=proposed+'px';element.style.width=(startWell+proposed-initial)+'px';};
   const stop=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',cancel);document.removeEventListener('keydown',escape);},cancel=()=>{stop();redraw();},escape=event=>{if(event.key==='Escape')cancel();},finish=()=>{stop();change('Resize log display',()=>{if(track)track.width=proposed;else setWellWidth(well,proposed);});};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',cancel);document.addEventListener('keydown',escape);
  };
 }
}
function registerWell(){brandedForm('Register a well',`<label class="field">Well name<input name="name" required maxlength="100" placeholder="TMB-01"></label><label class="field">UWI / API (optional)<input name="uwi" maxlength="100"></label><label class="field">Aliases (comma separated)<input name="aliases" maxlength="500"></label>`,async f=>{const name=String(f.get('name')).trim(),uwi=String(f.get('uwi')||'').trim(),registry=ctx.host.getState().wellDrafts||=[];if(registry.some(w=>(w.name||w.id).toLowerCase()===name.toLowerCase()||uwi&&w.uwi===uwi))throw new Error('This name/UWI is already registered. Import another run into the existing well.');const id=uid();registry.push({id,name,uwi,aliases:String(f.get('aliases')||'').split(',').map(v=>v.trim()).filter(Boolean),status:'User registered',createdAt:new Date().toISOString()});ctx.host.save();await ctx.host.flush();openWell(id);});}
function addToTrack(payload,wellId=null,trackId=null,at=null){
 if(payload.kind==='well'){openWell(payload.wellId);return;}
 if(payload.kind==='well-view'){change('Reorder wells',()=>{const wells=book().wells,index=wells.findIndex(w=>w.id===payload.id),target=wells.findIndex(w=>w.id===wellId);if(index<0)return;const [w]=wells.splice(index,1);wells.splice(target<0?wells.length:target,0,w);});return;}
 if(payload.kind==='track'){change('Move track',()=>{const from=book().wells.find(w=>w.id===payload.wellId),to=book().wells.find(w=>w.id===wellId);if(!from||!to)return;const index=from.tracks.findIndex(t=>t.id===payload.trackId);if(index<0)return;const [track]=from.tracks.splice(index,1);const position=to.tracks.findIndex(t=>t.id===trackId);to.tracks.splice(at??(position<0?to.tracks.length:position),0,track);});return;}
 const dataset=ds(payload.datasetId);if(!dataset)throw new Error('The selected source is not active.');change('Add source curve',()=>{let well=book().wells.find(w=>w.id===wellId)||book().wells.find(w=>w.wellId===dataset.well);if(!well)well=addWell(book(),dataset.well||'Unassigned evidence',[]);const track=addCurve(well,dataset,payload.columnId,trackId);if(at!==null){well.tracks=well.tracks.filter(t=>t.id!==track.id);well.tracks.splice(at,0,track);}book().selected={wellId:well.id,trackId:track.id,curveId:track.curves.at(-1).id};board().focus='logs';});
}
function zoom(factor,center=null,well=null){if(!book().wells.some(w=>wellExtent(w)))throw new Error('Wait for the retained log samples to load before changing depth.');change('Depth navigation',()=>{const w=well||selectedObjects(book()).well,range=w?visibleRange(w):book().range||fitRange(),mid=center??(range[0]+range[1])/2,span=Math.max(.001,(range[1]-range[0])*factor),t=(mid-range[0])/(range[1]-range[0]);const next=[mid-span*t,mid+span*(1-t)];if(w&&w.linked===false)w.range=next;else book().range=next;});}
function pickTop(well,depth){brandedForm('Pick a formation top',`<label class="field">Formation / marker name<input name="name" required maxlength="100"></label><label class="field">Source depth (metres)<input name="depth" type="number" step="any" required value="${depth.toFixed(4)}"></label><label class="field">Evidence / uncertainty notes<textarea name="notes" required maxlength="2000"></textarea></label><p>${esc(well.wellId)} Â· ${esc(well.basis||'source reference')}. A matching name on another well draws a user-picked correlation, not an automatic geological interpretation.</p>`,f=>{change('Pick formation top',()=>{book().markers.push({id:uid(),wellId:well.wellId,name:f.get('name').trim(),depth:Number(f.get('depth')),notes:f.get('notes'),reference:well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(data().find(d=>d.family==='logs'&&d.well===well.wellId)),verticalDatum:data().find(d=>d.family==='logs'&&d.well===well.wellId)?.references?.verticalDatum||'',color:'#b78540',createdAt:new Date().toISOString()});book().pickTop=false;});});}
function provenance(curve){const dataset=ds(curve.datasetId),c=col(dataset,curve.columnId);if(!dataset||!c)throw new Error('This original source is no longer active. Restore it before opening provenance.');ctx.host.modal('Curve source and provenance',`<h3>${esc(curve.name)}</h3><dl class="iw-metrics">${Object.entries({well:dataset.well,run:dataset.name,originalMnemonic:c.mnemonic,columnIdentity:c.id,sourceUnit:sourceUnit(c)||'Unresolved',sourceFingerprint:dataset.sourceSha256||'Not recorded',parserVersion:dataset.parserVersion||'',calculationRun:dataset.scientificRunId||'Original evidence',reviewState:dataset.scientificApproval?'Scientifically approved':'Scientific approval not granted'}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p>Display labels, colours and axis settings do not modify stored samples.</p>`);}
function templates(){const {well}=selectedObjects(book());if(!well)throw new Error('Select a well before saving or applying a template.');const b=board();ctx.host.modal('Well-section templates',`<button id="wb-save-template">Save selected well as template</button><label class="iw-check"><input id="wb-template-all" type="checkbox">Apply to all wells in this workbook</label>${b.templates.map(t=>`<div class="status-row"><span>${esc(t.name)}</span><button data-wb-apply-template="${t.id}">Apply template</button></div>`).join('')||'<p>No saved templates.</p>'}<p>Confirmed curve types and units take priority; unclassified curves require exact mnemonics. Missing or ambiguous runs remain for review.</p>`);
 $('#wb-save-template').onclick=()=>brandedForm('Save well-section template','<label class="field">Template name<input name="name" required maxlength="100"></label>',f=>change('Save template',()=>b.templates.push({id:uid(),schemaVersion:2,name:f.get('name'),indexTrack:true,correlation:book().correlation,hiddenMarkers:[...(book().hiddenMarkers||[])],tracks:well.tracks.map(t=>({name:t.name,width:t.width,curves:t.curves.map(c=>({mnemonic:col(ds(c.datasetId),c.columnId)?.mnemonic,propertyType:col(ds(c.datasetId),c.columnId)?.propertyType,unit:c.unit,color:c.color,log:c.log,reverse:c.reverse,min:c.min,max:c.max,visible:c.visible,dashed:c.dashed,fill:c.fill,fillOpacity:c.fillOpacity}))}))})));
 document.querySelectorAll('[data-wb-apply-template]').forEach(button=>button.onclick=()=>{const template=b.templates.find(t=>t.id===button.dataset.wbApplyTemplate),targets=$('#wb-template-all').checked?book().wells:[well],proposals=targets.map(target=>{const proposed=structuredClone(target),missing=applyTemplate(proposed,template,data());return {target,proposed,missing};});ctx.host.modal('Review template associations',`<p>Review all well associations before replacing their display tracks. Missing and ambiguous matches remain unbound.</p>${proposals.map(p=>`<h3>${esc(p.target.name)}</h3><p>${p.proposed.tracks.reduce((n,t)=>n+t.curves.length,0)} unique curve matches</p><ul>${p.missing.map(v=>`<li>${esc(v)}</li>`).join('')||'<li>No missing or ambiguous curves</li>'}</ul>`).join('')}<button id="wb-confirm-template">Apply reviewed associations</button>`);$('#wb-confirm-template').onclick=()=>{change('Apply reviewed template',()=>{for(const p of proposals)p.target.tracks=p.proposed.tracks;if(template.schemaVersion===2){book().correlation=template.correlation;book().hiddenMarkers=[...(template.hiddenMarkers||[])];}});$('#dialog').close();};});
}

function versions(){const b=board();ctx.host.modal('Workbook versions',`<button id="wb-save-version">Save named workbook version</button>${b.versions.map(v=>`<div class="status-row"><span>${esc(v.name)}<small>${esc(new Date(v.time).toLocaleString())}</small></span><button data-wb-restore-version="${v.id}">Restore display</button></div>`).join('')||'<p>No saved versions. Undo/redo tracks edits during this session.</p>'}`);$('#wb-save-version').onclick=()=>brandedForm('Save workbook version','<label class="field">Version name<input name="name" required maxlength="100"></label>',f=>change('Save workbook version',()=>{b.versions.push({id:uid(),name:f.get('name'),time:new Date().toISOString(),book:structuredClone(book())});if(b.versions.length>5)b.versions.shift();}));document.querySelectorAll('[data-wb-restore-version]').forEach(button=>button.onclick=()=>{change('Restore workbook version',()=>{const saved=b.versions.find(v=>v.id===button.dataset.wbRestoreVersion);const current=book();const restored=structuredClone(saved.book);restored.id=current.id;b.books[b.books.indexOf(current)]=restored;});$('#dialog').close();});}
function recipes(){const b=board();ctx.host.modal('Reviewed workflow recipes',`<p>Recipes reopen saved method configurations for the selected well. Each step must be mapped, confirmed and run explicitly; results are never invented or automatically chained.</p><button id="wb-save-recipe">Save current analysis steps</button>${b.recipes.map(r=>`<div class="status-row"><span>${esc(r.name)} Â· ${r.steps.length} steps</span><button data-wb-open-recipe="${r.id}">Open steps</button></div>`).join('')}`);$('#wb-save-recipe').onclick=()=>{const steps=ctx.state().windows.filter(w=>w.method&&w.tool!=='logs').map(w=>({method:w.method,parameters:structuredClone(w.parameters||{}),notes:w.notes||''}));if(!steps.length){ctx.host.toast('Configure at least one analysis step first.');return;}brandedForm('Save workflow recipe','<label class="field">Recipe name<input name="name" required maxlength="100"></label>',f=>change('Save recipe',()=>b.recipes.push({id:uid(),name:f.get('name'),steps})));};document.querySelectorAll('[data-wb-open-recipe]').forEach(button=>button.onclick=()=>{const r=b.recipes.find(r=>r.id===button.dataset.wbOpenRecipe);$('#dialog').close();for(const step of r.steps)ctx.openMethod(step.method,step);});}

function crossplotSetup(){const {curve,well,track}=selectedObjects(book()),dataset=ds(curve?.datasetId||track?.curves[0]?.datasetId||well?.tracks[0]?.curves[0]?.datasetId);if(!dataset)throw new Error('Select a source curve before opening a crossplot.');brandedForm('Crossplot from selected well',`<p>${esc(dataset.well)} Â· ${esc(dataset.name)}. Both axes use the same stored rows; no implicit resampling.</p>${['x','y'].map((role,j)=>`<label class="field">${role.toUpperCase()} curve<select name="${role}">${numericColumns(dataset).filter(c=>c.id!==indexColumn(dataset)?.id).map((c,i)=>`<option value="${c.id}" ${i===j?'selected':''}>${esc(c.mnemonic)} Â· ${esc(sourceUnit(c)||'unresolved')}</option>`).join('')}</select></label>`).join('')}`,async f=>{if(f.get('x')===f.get('y'))throw new Error('Choose two different columns.');await load(dataset);change('Open crossplot',()=>book().crossplot={datasetId:dataset.id,x:f.get('x'),y:f.get('y')});});}
function brushedIndices(brush){const source=cache.get(brush.datasetId);if(!source)return [];if(Number.isInteger(brush.row))return source.rows[brush.row]?[brush.row]:[];const x=source.columns.findIndex(c=>c.id===brush.x),y=source.columns.findIndex(c=>c.id===brush.y);return source.rows.flatMap((r,i)=>finite(r[x])&&finite(r[y])&&r[x]>=brush.xmin&&r[x]<=brush.xmax&&r[y]>=brush.ymin&&r[y]<=brush.ymax?[i]:[]);}
function brushRanges(brush){const indices=brushedIndices(brush),ranges=[];for(const i of indices){const last=ranges.at(-1);if(last&&last[1]===i-1)last[1]=i;else ranges.push([i,i]);}if(ranges.length>1000)throw new Error('Refine the crossplot brush to at most 1,000 contiguous row ranges before calculating.');return ranges;}
function crossplotView(){const config=book().crossplot,source=cache.get(config.datasetId),dataset=ds(config.datasetId);if(!source)return '';const xi=source.columns.findIndex(c=>c.id===config.x),yi=source.columns.findIndex(c=>c.id===config.y),xr=rangeOf(source.rows.map(r=>r[xi])),yr=rangeOf(source.rows.map(r=>r[yi]));if(!xr||!yr)return '<section class="wb-crossplot"><p>No finite pairs for this crossplot.</p><button data-wb-action="close-crossplot">Close</button></section>';const valid=source.rows.map((r,i)=>({r,i})).filter(p=>finite(p.r[xi])&&finite(p.r[yi])),step=Math.max(1,Math.ceil(valid.length/2000)),di=source.columns.findIndex(c=>c.id===indexColumn(dataset)?.id),factor=depthFactor(sourceUnit(source.columns[di]));const selected=new Set(book().brush?brushedIndices(book().brush):[]);
 return `<section class="wb-crossplot"><header><strong>${esc(dataset.well)} Â· ${esc(col(dataset,config.x)?.mnemonic)} Ã— ${esc(col(dataset,config.y)?.mnemonic)}</strong>${book().brush?'<button data-wb-action="record-crossplot">Record observation</button>':''}<button data-wb-action="close-crossplot" aria-label="Close crossplot">${icon('close')}</button></header><p>Click a point or drag to select a range. Range selection includes all retained pairs. The preview shows up to 2,000 points.</p><svg id="wb-crossplot-svg" viewBox="0 0 600 300" role="img" aria-label="Linked source crossplot" data-xmin="${xr[0]}" data-xmax="${xr[1]}" data-ymin="${yr[0]}" data-ymax="${yr[1]}"><path d="M45 15v245h535" stroke="#a5b9af" fill="none"/>${valid.filter((_,i)=>i%step===0).map(({r,i})=>{const z=factor&&finite(r[di])?shownDepth(book().wells.find(w=>w.wellId===dataset.well)||{},dataset,r[di]*factor):null,interval=book().selectionRange,active=selected.has(i)||interval&&finite(z)&&z>=interval.top&&z<=interval.base;return `<circle data-wb-sample-row="${i}" cx="${45+(r[xi]-xr[0])/(xr[1]-xr[0])*525}" cy="${260-(r[yi]-yr[0])/(yr[1]-yr[0])*240}" r="${active?2.5:1.6}" fill="${active?'#b78540':'#087c73'}" opacity=".65"/>`;}).join('')}<text x="45" y="285">${xr[0].toPrecision(4)}</text><text x="510" y="285">${xr[1].toPrecision(4)}</text><text x="2" y="25">${yr[1].toPrecision(4)}</text><text x="2" y="260">${yr[0].toPrecision(4)}</text><rect id="wb-brush-rect" fill="#b78540" opacity=".15" width="0" height="0"/></svg><small>${valid.length.toLocaleString()} valid pairs${book().brush?' Â· '+selected.size.toLocaleString()+' brushed samples':''} Â· X ${esc(sourceUnit(col(dataset,config.x))||'unit unresolved')} Â· Y ${esc(sourceUnit(col(dataset,config.y))||'unit unresolved')}</small></section>`;
}

function exportEvidence(dataset){const {preview,chunks,columnStatistics,...retained}=dataset;return retained;}
function exportCurve(curve){const source=cache.get(curve.datasetId),dataset=ds(curve.datasetId);if(!source)throw new Error('Wait for the complete source to load before exporting.');const ci=source.columns.findIndex(c=>c.id===curve.columnId),di=source.columns.findIndex(c=>c.id===(curve.indexColumnId||indexColumn(dataset)?.id));if(di<0||ci<0)throw new Error('Select a retained curve and depth/index column first.');const quote=v=>'"'+(typeof v==='string'&&/^[=+@-]/.test(v)?"'"+v:String(v??'')).replaceAll('"','""')+'"',column=source.columns[ci],metadata=JSON.stringify({schemaVersion:1,dataset:exportEvidence(dataset),curve,limitations:'Full retained source samples; ghost and display transforms do not rewrite source values.'});const text=[[source.columns[di].mnemonic+' ['+sourceUnit(source.columns[di])+']'+(dataset.references?.depthReference?' · '+dataset.references.depthReference:''),column.mnemonic+' ['+sourceUnit(column)+']'+(column.porosityBasis?' · '+column.porosityBasis+' porosity':''),'Interpretation metadata (JSON; first row)'],...source.rows.map((r,i)=>[r[di],r[ci],i===0?metadata:''])].map(row=>row.map(quote).join(',')).join('\r\n');ctx.host.download('StrataX-'+curve.name.replace(/[^\w-]/g,'_')+'.csv',new Blob([text],{type:'text/csv'}));}
function exportView(){const b=book();ctx.host.modal('Export workbook',`<p>Export the actual displayed curves and picked tops, or retain the editable view metadata. Original files stay in project storage.</p><div class="actions"><button id="wb-export-svg">Export plotted SVG</button><button id="wb-export-layout">Export view metadata</button><button id="wb-import-layout">Import view metadata</button></div>`);$('#wb-export-layout').onclick=()=>ctx.host.download('StrataX-view.json',new Blob([JSON.stringify({schemaVersion:1,projectId:ctx.project().id,book:b},null,2)],{type:'application/json'}));$('#wb-import-layout').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>512000)throw new Error('Choose view metadata below 500 KiB.');const parsed=JSON.parse(await file.text());if(parsed.schemaVersion!==1||parsed.projectId!==ctx.project().id||!Array.isArray(parsed.book?.wells)||parsed.book.wells.length>30)throw new Error('Choose a view exported from this project.');const clean=validateBook(parsed.book);change('Import workbook view',()=>{clean.id=uid();board().books.push(clean);board().activeBook=clean.id;});$('#dialog').close();}catch(e){fail(e);}};input.click();};$('#wb-export-svg').onclick=()=>{let x=0,elements=[],exportedBooks=new Map();for(const well of document.querySelectorAll('.wb-well')){const width=well.offsetWidth,pane=board().books.find(b=>b.id===well.closest("[data-wb-pane]")?.dataset.wbPane)||book(),displayWell=pane.wells.find(w=>w.id===well.dataset.wbWell);exportedBooks.set(pane.id,pane);elements.push(`<text x="${x+10}" y="22" font-family="sans-serif" font-size="14">${esc(displayWell?.name||"Displayed well")}</text>`);let tx=x;for(const track of well.querySelectorAll('.wb-depth-track,.wb-track')){const svg=track.querySelector('svg');if(svg){const copy=svg.cloneNode(true);copy.setAttribute('width',track.offsetWidth);copy.setAttribute('height','620');elements.push(`<g transform="translate(${tx} 125)">${copy.outerHTML}</g>`);const header=track.querySelector('header')?.innerText||'';header.split('\n').slice(0,5).forEach((line,j)=>elements.push(`<text x="${tx+5}" y="${45+j*14}" font-family="sans-serif" font-size="10">${esc(line)}</text>`));}tx+=track.offsetWidth;}x+=width+24;}ctx.host.download('StrataX-workbook.svg',new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${Math.max(600,x)}" height="800"><metadata>${esc(JSON.stringify({schemaVersion:1,projectId:ctx.project().id,books:[...exportedBooks.values()],evidence:data().filter(d=>[...exportedBooks.values()].some(pane=>pane.wells.some(w=>w.tracks.some(t=>t.curves.some(c=>c.datasetId===d.id))))).map(exportEvidence),limitations:"Plotted display envelope; complete retained samples are available through curve CSV."}))}</metadata><rect width="100%" height="100%" fill="white"/>${elements.join('')}<text x="10" y="785" font-family="sans-serif" font-size="10">Stored source curves Â· displayed min/max envelope Â· source references retained Â· ${esc(b.name)}</text></svg>`],{type:'image/svg+xml'}));};}
function validateBook(value){const markerIds=new Map();const result=freshBook(String(value.name||'Imported workbook').slice(0,100));result.range=validRange(value.range)?value.range:null;for(const w of value.wells){if(typeof w.wellId!=='string'||!Array.isArray(w.tracks)||w.tracks.length>30)throw new Error('Invalid well/track metadata.');const well={id:uid(),wellId:w.wellId,name:String(w.name||w.wellId).slice(0,120),tracks:[],offset:finite(w.offset)?w.offset:0,visible:w.visible!==false,linked:w.linked!==false,basis:['MD','TVD','TVDSS','Source reference'].includes(w.basis)?w.basis:'Source reference'};for(const t of w.tracks){if(!Array.isArray(t.curves)||t.curves.length>12)throw new Error('Invalid track metadata.');const track={id:uid(),name:String(t.name||'Track').slice(0,120),width:Math.max(MIN_TRACK_WIDTH,Math.min(MAX_TRACK_WIDTH,Number(t.width)||DEFAULT_TRACK_WIDTH)),curves:[]};well.tracks.push(track);for(const c of t.curves){const dataset=ds(c.datasetId);if(!dataset||!col(dataset,c.columnId))throw new Error('The imported view references an unavailable source.');addCurve(well,dataset,c.columnId,track.id);const curve=track.curves.at(-1);for(const prop of ['log','reverse','dashed','visible'])if(typeof c[prop]==='boolean')curve[prop]=c[prop];if(/^#[0-9a-f]{6}$/i.test(c.color))curve.color=c.color;for(const prop of ['min','max'])curve[prop]=finite(c[prop])?c[prop]:null;curve.fill=['left','right'].includes(c.fill)?c.fill:'none';curve.fillOpacity=finite(c.fillOpacity)?Math.max(0,Math.min(1,c.fillOpacity)):.12;curve.name=String(c.name||curve.name).slice(0,120);if(c.indexColumnId&&col(dataset,c.indexColumnId))curve.indexColumnId=c.indexColumnId;if(c.ghostSourceWell){const transform=c.ghostTransform;if(c.ghostSourceWell!==dataset.well||!transform||transform.kind!=='interwell-ghost-display'||transform.sourceWellId!==c.ghostSourceWell||transform.targetWellId!==well.wellId||!Array.isArray(transform.anchors)||transform.anchors.length>100||!Array.isArray(transform.sourceVersions))throw new Error('Invalid ghost source or display transformation.');if(transform.anchors.some((a,i)=>!finite(a.source)||!finite(a.target)||i&&(a.source<=transform.anchors[i-1].source||a.target<=transform.anchors[i-1].target)))throw new Error('Ghost anchors must remain finite and increasing.');curve.ghostSourceWell=c.ghostSourceWell;curve.ghostTransform=structuredClone(transform);}}}well.range=validRange(w.range)?w.range:null;result.wells.push(well);}result.markers=(Array.isArray(value.markers)?value.markers:[]).slice(0,500).map(m=>{if(!finite(m.depth)||typeof m.wellId!=='string'||typeof m.name!=='string')throw new Error('Invalid picked-top metadata.');const id=uid();if(m.id)markerIds.set(m.id,id);return {id,wellId:m.wellId,name:m.name.slice(0,100),depth:m.depth,notes:String(m.notes||'').slice(0,2000),reference:String(m.reference||'Source reference').slice(0,80),verticalDatum:String(m.verticalDatum||'').slice(0,100),color:'#b78540'};});result.flatten=typeof value.flatten==='string'?value.flatten.slice(0,100):null;result.correlation=value.correlation===true;result.hiddenMarkers=Array.isArray(value.hiddenMarkers)?value.hiddenMarkers.filter(id=>typeof id==='string').slice(0,2000).map(id=>markerIds.get(id)||id):[];for(const well of result.wells)for(const track of well.tracks)for(const curve of track.curves)if(curve.ghostTransform)for(const anchor of curve.ghostTransform.anchors){anchor.sourceMarkerId=markerIds.get(anchor.sourceMarkerId)||anchor.sourceMarkerId;anchor.targetMarkerId=markerIds.get(anchor.targetMarkerId)||anchor.targetMarkerId;}return result;}
const validRange=r=>Array.isArray(r)&&r.length===2&&r.every(finite)&&r[1]>r[0];

function contextMenu(target,x,y){const returnFocus=document.activeElement;contextTarget=target;document.querySelector('#wb-context-menu')?.remove();const menu=document.createElement('div');menu.id='wb-context-menu';menu.className='wb-context-menu';menu.setAttribute('role','menu');const actions=target.kind==='source'?[['add','Add to canvas'],['source-provenance','Source provenance']]:target.kind==='curve'?[['properties','Curve properties'],['duplicate-curve','Duplicate overlay'],['crossplot','Crossplot'],['calculate','Calculate from selection'],['repair','Condition this curve…'],['curve-export','Export curve CSV'],...(ds(book().wells.find(w=>w.id===target.wellId)?.tracks.find(t=>t.id===target.trackId)?.curves.find(c=>c.id===target.curveId)?.datasetId)?.scientificRunId?[['calculation','Open calculation settings']]:[]),['provenance','Source & provenance'],['remove-curve','Remove from view']]:[['properties','Track properties'],['widths','Well / track widths'],['duplicate-track','Duplicate track'],['remove-track','Remove from view']];menu.innerHTML=actions.map(([id,label])=>`<button role="menuitem" data-wb-context-action="${id}">${label}</button>`).join('');menu.insertAdjacentHTML('beforeend',`<hr>${(target.kind==='source'?['Raster digitization','Live source connection']:target.kind==='curve'?['Interactive sample editor','Image interpretation','3D display']:['Image track','Core photo track']).map(label=>`<button role="menuitem" disabled title="Not available in this release; planned interface.">${label}</button>`).join('')}`);menu.style.left=Math.max(8,Math.min(x,innerWidth-230))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-(actions.length+3)*32-12))+'px';document.body.append(menu);menu.querySelector('button')?.focus();menu.querySelectorAll('button').forEach(button=>button.onclick=()=>{menu.remove();try{if(target.kind==='source'){if(button.dataset.wbContextAction==='add')addToTrack({...target,kind:'curve'});else provenance({datasetId:target.datasetId,columnId:target.columnId,name:col(ds(target.datasetId),target.columnId)?.mnemonic});return;}book().selected={wellId:target.wellId,trackId:target.trackId,curveId:target.curveId};action(button.dataset.wbContextAction);}catch(e){fail(e);}});menu.onkeydown=e=>{const buttons=[...menu.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();e.stopPropagation();menu.remove();if(returnFocus?.isConnected)returnFocus.focus();return;}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}};}

function action(name){const b=book(),s=board(),{well,track,curve}=selectedObjects(b);switch(name){
 case 'widths':return widthSettings();case 'compact-wells':return change('Use slim well tracks',()=>{for(const w of b.wells.filter(w=>w.visible!==false))for(const t of w.tracks)t.width=MIN_TRACK_WIDTH;});case 'fit-wells':return fitWells();
 case 'register':return registerWell();case 'import':return ctx.host.openImporter({family:'logs',well:well?.wellId});case 'all-wells':board().initialLogDisplayPrepared=true;return chooseWells();case 'crossplot':return crossplotSetup();case 'templates':return templates();case 'recipes':return recipes();case 'versions':return versions();case 'export':return exportView();
 case 'new-book':board().initialLogDisplayPrepared=true;return brandedForm('New workbook','<label class="field">Name<input name="name" required maxlength="100"></label>',f=>change('Create workbook',()=>{const w=freshBook(f.get('name'));s.books.push(w);s.activeBook=w.id;}));
 case 'manage-book':return brandedForm('Manage workbook',`<label class="field">Name<input name="name" required maxlength="100" value="${esc(b.name)}"></label><label class="iw-check"><input name="close" type="checkbox" ${s.books.length===1?'disabled':''}>Close this workbook (source data is retained)</label>`,f=>change('Manage workbook',()=>{if(f.has('close')){s.books=s.books.filter(w=>w.id!==b.id);s.activeBook=s.books[0].id;}else b.name=f.get('name');}));
 case 'undo':case 'redo':{const from=name==='undo'?undo:redo,to=name==='undo'?redo:undo,stack=from.get(key)||[],entry=stack.pop();if(!entry)return;const reverse=to.get(key)||[];reverse.push({label:entry.label,state:snapshot()});to.set(key,reverse);restoreSnapshot(entry.state);ctx.host.save();return redraw();}
 case 'zoom-in':return zoom(.5);case 'zoom-out':return zoom(2);case 'fit':return change('Fit depth',()=>{b.range=null;for(const w of b.wells)w.range=null;});
 case 'rulers':if(!well)throw new Error('Select a well to configure depth rulers.');return brandedForm('Reference depth rulers',`<p>Additional vertical references require retained survey/datum evidence. Feet shows the current reference in a different unit.</p>${[...new Set(['ft',...domainOptions(well).filter(ref=>ref!=='Source reference')])].map(ref=>`<label><input type="checkbox" name="ruler" value="${esc(ref)}" ${well.rulers?.includes(ref)?'checked':''}>${ref==='ft'?'Current reference in feet':esc(ref)}</label>`).join('')}`,f=>change('Reference rulers',()=>well.rulers=f.getAll('ruler')));
 case 'link':return change('Toggle linked depths',()=>{b.linked=!b.linked;for(const w of b.wells){w.range=w.range||b.range||fitRange();w.linked=b.linked;}});
 case 'tops':return change('Toggle top picking',()=>b.pickTop=!b.pickTop);case 'correlate':return change('Toggle top correlations',()=>b.correlation=!b.correlation);
 case 'flatten':return brandedForm('Flatten on a picked formation top',`<label class="field">Marker<select name="name"><option value="">No flattening</option>${[...new Set(b.markers.map(m=>m.name))].map(n=>`<option ${b.flatten===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><p>Only wells with this user-picked top receive an offset. Source depths are unchanged.</p>`,f=>change('Formation flattening',()=>{b.flatten=f.get('name')||null;b.range=null;}));
 case 'empty-track':if(!well)throw new Error('Select a well first.');return change('Add track',()=>{const t={id:uid(),name:'New track',width:DEFAULT_TRACK_WIDTH,curves:[]};well.tracks.push(t);b.selected={wellId:well.id,trackId:t.id};});
 case 'duplicate-track':if(!track)throw new Error('Select a track first.');return change('Duplicate track',()=>{const copy=structuredClone(track);copy.id=uid();copy.name+=' copy';for(const c of copy.curves)c.id=uid();well.tracks.splice(well.tracks.indexOf(track)+1,0,copy);b.selected={wellId:well.id,trackId:copy.id};});
 case 'duplicate-curve':if(!curve)throw new Error('Select a curve first.');return change('Duplicate overlay',()=>{const copy={...curve,id:uid(),name:curve.name+' copy',dashed:true};track.curves.push(copy);b.selected.curveId=copy.id;});
 case 'remove-track':if(track)return change('Remove track display',()=>{well.tracks=well.tracks.filter(t=>t.id!==track.id);b.selected={wellId:well.id};});return;
 case 'remove-curve':if(curve)return change('Remove curve display',()=>{track.curves=track.curves.filter(c=>c.id!==curve.id);delete b.selected.curveId;});return;
 case 'properties':s.focus='logs';ctx.state().inspector=true;return redraw();case 'curve-export':if(curve)return exportCurve(curve);throw new Error('Select a curve first.');case 'provenance':if(curve)return provenance(curve);throw new Error('Select a curve first.');
 case 'record-crossplot':{
  const brush=b.brush,dataset=ds(brush?.datasetId);
  if(!dataset||dataset.isProposal)throw new Error('Select samples from a retained curve before recording an observation.');
  const rows=brushRanges(brush);
  if(!rows.length)throw new Error('Select at least one crossplot sample.');
  return brandedForm('Record crossplot observation','<label class="field">Interpretation<input name="label" required maxlength="120"></label><label class="field">Evidence and uncertainty<textarea name="evidence" required maxlength="2000"></textarea></label>',form=>{
   ctx.state().annotations.push({id:uid(),kind:'interval',tool:'lithology',label:form.get('label'),evidence:form.get('evidence'),wellId:dataset.well,datasetId:dataset.id,geometry:{depthReference:sourceBasis(dataset),indexColumnId:indexColumn(dataset)?.id,curveIds:[brush.x,brush.y],rowRanges:rows,sourceSha256:dataset.sourceSha256||null},createdAt:new Date().toISOString()});
   ctx.host.save();
  });
 }
 case 'calculation':if(curve&&ds(curve.datasetId)?.scientificRunId)return ctx.inspectRun(ds(curve.datasetId).scientificRunId).catch(fail);return;
 case 'repair':return ctx.chooseMethod('qc');case 'calculate':return ctx.chooseMethod();case 'back-to-logs':s.focus='logs';ctx.host.save();return redraw();case 'close-crossplot':return change('Close crossplot',()=>{b.crossplot=null;b.brush=null;});case 'clear-selection':return change('Clear selected samples',()=>{b.selectionRange=null;b.brush=null;});
 default:throw new Error('This canvas action is not available.');
}}

export function bindWellCanvas(){
 const root=document.querySelector('.iw');if(!root)return;
 root.addEventListener('pointerdown',e=>{const pane=e.target.closest('[data-wb-pane]');if(pane){board().activeBook=pane.dataset.wbPane;ctx.host.save();}},{capture:true});
 root.addEventListener('wheel',e=>{const pane=e.target.closest('[data-wb-pane]');if(pane)board().activeBook=pane.dataset.wbPane;},{capture:true,passive:true});
 root.addEventListener('focusin',e=>{const pane=e.target.closest('[data-wb-pane]');if(pane)board().activeBook=pane.dataset.wbPane;});
 if(!outsideBound){outsideBound=true;document.addEventListener('pointerdown',event=>{if(!event.target.closest('#wb-context-menu'))document.querySelector('#wb-context-menu')?.remove();});}
 for(const el of root.querySelectorAll('.wb-board-scroll')){const id=el.closest('[data-wb-pane]')?.dataset.wbPane||board().activeBook,target=board().books.find(b=>b.id===id);if(target?.scroll){el.scrollLeft=target.scroll.left;el.scrollTop=target.scroll.top;}el.onscroll=()=>{if(target)target.scroll={left:el.scrollLeft,top:el.scrollTop};};}
 const safe=fn=>async e=>{try{await fn(e);}catch(error){fail(error);}};root.querySelectorAll('[data-wb-tree-key]').forEach(details=>details.ontoggle=()=>{const set=new Set(board().treeOpen||[]);const before=set.has(details.dataset.wbTreeKey);if(details.open)set.add(details.dataset.wbTreeKey);else set.delete(details.dataset.wbTreeKey);if(before!==details.open){board().treeOpen=[...set];ctx.host.save();}});
 bindWidthHandles(root);
 root.querySelectorAll('[data-wb-action]').forEach(button=>button.onclick=safe(()=>action(button.dataset.wbAction)));
 root.querySelectorAll('[data-wb-book]').forEach(button=>button.onclick=()=>{board().activeBook=button.dataset.wbBook;board().focus='logs';ctx.host.save();redraw();});
 root.querySelectorAll('[data-wb-open-well]').forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();openWell(button.dataset.wbOpenWell);});
 root.querySelectorAll('[data-wb-import-well]').forEach(button=>button.onclick=safe(()=>ctx.host.openImporter({family:'logs',well:button.dataset.wbImportWell})));
 root.querySelectorAll('[data-wb-add-curve]').forEach(button=>button.onclick=safe(()=>{const [datasetId,columnId]=button.dataset.wbAddCurve.split(':');addToTrack({kind:'curve',datasetId,columnId},selectedObjects(book()).well?.id,selectedObjects(book()).track?.id);}));
 root.querySelectorAll('[data-wb-select]').forEach(button=>button.onclick=e=>{if(e.target.closest('[data-wb-well-menu]'))return;const picked=JSON.parse(button.dataset.wbSelect);const w=book().wells.find(w=>w.id===picked.wellId),t=w?.tracks.find(t=>t.id===picked.trackId),c=t?.curves.find(c=>c.id===picked.curveId);if(w)select(w,t,c);});
 root.querySelectorAll('[data-wb-new-track]').forEach(button=>button.onclick=()=>{book().selected={wellId:button.dataset.wbNewTrack};action('empty-track');});
 root.querySelectorAll('[data-wb-insert]').forEach(button=>button.onclick=()=>{const [id,index]=button.dataset.wbInsert.split(':');change('Insert track',()=>book().wells.find(w=>w.id===id).tracks.splice(Number(index),0,{id:uid(),name:'New track',width:DEFAULT_TRACK_WIDTH,curves:[]}));});
 root.querySelectorAll('[data-wb-well-menu]').forEach(button=>button.onclick=()=>{const well=book().wells.find(w=>w.id===button.dataset.wbWellMenu);book().selected={wellId:well.id};ctx.host.modal('Manage well display',`<div class="project-menu"><button id="wb-well-properties">Display properties</button><button id="wb-remove-well">Remove well from this workbook</button><button id="wb-top-table">Review / edit formation tops</button></div><p>Source files, imported curves and registered well identity remain stored.</p>`);$('#wb-well-properties').onclick=()=>{$('#dialog').close();select(well);};$('#wb-remove-well').onclick=()=>{change('Remove well display',()=>{book().wells=book().wells.filter(w=>w.id!==well.id);book().selected=null;});$('#dialog').close();};$('#wb-top-table').onclick=()=>topTable(well);});
 root.querySelectorAll('[data-wb-context]').forEach(element=>{element.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();contextMenu(JSON.parse(element.dataset.wbContext),e.clientX,e.clientY);};element.onkeydown=e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){e.preventDefault();e.stopPropagation();const r=element.getBoundingClientRect();contextMenu(JSON.parse(element.dataset.wbContext),r.left+20,r.top+10);}};});
 root.querySelectorAll('[data-wb-zone-boundary]').forEach(boundary=>boundary.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();event.stopPropagation();root.dispatchEvent(new CustomEvent('pp-edit-zone',{detail:{zoneId:boundary.dataset.wbZoneBoundary,edge:boundary.dataset.edge}}));}});
 $('#wb-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;redraw();const input=$('#wb-search');input.focus();input.setSelectionRange(pos,pos);});
 root.querySelectorAll('[data-wb-drag]').forEach(element=>element.ondragstart=e=>{e.stopPropagation();e.dataTransfer.setData('application/x-stratax-object',element.dataset.wbDrag);e.dataTransfer.effectAllowed='copyMove';});
 root.querySelectorAll('[data-wb-drop]').forEach(element=>{element.ondragover=e=>{e.preventDefault();e.stopPropagation();element.classList.add('wb-drop-active');};element.ondragleave=()=>element.classList.remove('wb-drop-active');element.ondrop=safe(e=>{e.preventDefault();e.stopPropagation();element.classList.remove('wb-drop-active');const raw=e.dataTransfer.getData('application/x-stratax-object');if(!raw)return;const payload=JSON.parse(raw);addToTrack(payload,element.dataset.wellId,element.dataset.trackId);});});
 root.querySelectorAll('[data-wb-visibility]').forEach(input=>{input.indeterminate=input.dataset.partial==='true';input.onclick=e=>e.stopPropagation();input.onchange=safe(()=>change('Change view visibility',()=>{const {id,wbVisibility:kind}=input.dataset,checked=input.checked;if(kind==='marker'){const hidden=new Set(book().hiddenMarkers||[]);if(checked)hidden.delete(id);else hidden.add(id);book().hiddenMarkers=[...hidden];}else if(kind==='well'){let well=book().wells.find(w=>w.wellId===id);if(!well&&checked){well=addWell(book(),id,logDatasets());well.name=ctx.host.getState().wellDrafts?.find(w=>w.id===id)?.name||id;}if(well)well.visible=checked;}else if(kind==='run'){const dataset=ds(id);toggleCurves(dataset,numericColumns(dataset).filter(c=>c.id!==indexColumn(dataset)?.id),checked);}else if(kind==='curve'){const split=id.lastIndexOf(':'),dataset=ds(id.slice(0,split));toggleCurves(dataset,[col(dataset,id.slice(split+1))],checked);}else if(kind==='type')for(const dataset of logDatasets())toggleCurves(dataset,numericColumns(dataset).filter(c=>c.id!==indexColumn(dataset)?.id&&(c.propertyType||'Unclassified')===id),checked);}));});
 root.querySelectorAll('[data-wb-inspect]').forEach(button=>button.onclick=safe(async()=>{const dataset=ds(button.dataset.wbInspect);await ctx.inspectDataset(dataset);}));
 root.querySelectorAll('[data-wb-retry]').forEach(button=>button.onclick=safe(async()=>{failures.delete(button.dataset.wbRetry);await load(ds(button.dataset.wbRetry));redraw();}));
 root.querySelectorAll('[data-wb-review-run]').forEach(button=>button.onclick=safe(()=>ctx.reviewRun(button.dataset.wbReviewRun)));
 root.querySelectorAll('#wb-range,[data-comparison-range]').forEach(form=>form.addEventListener('submit',safe(e=>{e.preventDefault();const f=new FormData(e.target),r=[Number(f.get('top')),Number(f.get('base'))];if(!validRange(r))throw new Error('Enter a finite base depth greater than the top.');change('Set displayed interval',()=>{const w=selectedObjects(book()).well;if(w?.linked===false)w.range=r;else book().range=r;});})));
 $('#wb-properties')?.addEventListener('submit',safe(e=>{e.preventDefault();const {well,track,curve}=selectedObjects(book()),f=new FormData(e.target),width=Number(f.get('width')||DEFAULT_TRACK_WIDTH),lo=f.get('min')===''?null:Number(f.get('min')),hi=f.get('max')===''?null:Number(f.get('max'));if(track&&(!Number.isFinite(width)||width<MIN_TRACK_WIDTH||width>MAX_TRACK_WIDTH))throw new Error('Track width must be 48â€“480 pixels.');if(curve&&(lo!==null&&!finite(lo)||hi!==null&&!finite(hi)||lo!==null&&hi!==null&&hi<=lo))throw new Error('Axis maximum must exceed its finite minimum.');if(curve&&f.has('log')&&(lo!==null&&lo<=0||hi!==null&&hi<=0))throw new Error('Logarithmic axis bounds must be positive.');change('Edit display properties',()=>{well.linked=f.has('linked');well.offset=Number(f.get('offset')||0);if(!domainOptions(well).includes(f.get('basis')))throw new Error('This depth domain is not supported by the active survey.');well.basis=f.get('basis');well.range=null;book().range=null;const target=curve||track||well;target.name=String(f.get('name')).trim();if(track)track.width=width;if(curve)Object.assign(curve,{color:f.get('color'),visible:f.has('visible'),log:f.has('log'),reverse:f.has('reverse'),dashed:f.has('dashed'),fill:f.get('fill')||'none',min:lo,max:hi,indexColumnId:f.get('indexColumnId')});});}));
 bindPlots(root);bindCrossplot();
}

function topTable(well){ctx.host.modal('Picked tops Â· '+esc(well.wellId),`<button id="wb-manual-top">Add top manually</button>${markerCatalog().filter(m=>m.imported&&m.wellId===well.wellId).map(m=>`<p>${esc(m.name)} Â· ${m.depth} m ${esc(m.reference)} Â· retained source pick</p>`).join('')}${book().markers.filter(m=>m.wellId===well.wellId).map(m=>`<div class="status-row"><span>${esc(m.name)} Â· ${m.depth.toFixed(2)} m</span><button data-wb-edit-top="${m.id}">Edit</button><button data-wb-delete-top="${m.id}">Remove</button></div>`).join('')}`);$('#wb-manual-top').onclick=()=>pickTop(well,visibleRange(well)[0]+offsetFor(well));document.querySelectorAll('[data-wb-delete-top]').forEach(button=>button.onclick=()=>{change('Remove picked top',()=>book().markers=book().markers.filter(m=>m.id!==button.dataset.wbDeleteTop));topTable(well);});document.querySelectorAll('[data-wb-edit-top]').forEach(button=>button.onclick=()=>{const m=book().markers.find(m=>m.id===button.dataset.wbEditTop);brandedForm('Edit picked top',`<label class="field">Name<input name="name" required value="${esc(m.name)}"></label><label class="field">Depth (m)<input name="depth" type="number" step="any" required value="${m.depth}"></label><label class="field">Evidence notes<textarea name="notes" required>${esc(m.notes)}</textarea></label>`,f=>change('Edit picked top',()=>Object.assign(m,{name:f.get('name'),depth:Number(f.get('depth')),notes:f.get('notes'),accepted:false,reviewedAt:null})));});}
function bindPlots(root){root.querySelectorAll('[data-wb-plot]').forEach(plot=>{const paneBook=board().books.find(b=>b.id===plot.closest('[data-wb-pane]')?.dataset.wbPane)||book(),well=paneBook.wells.find(w=>w.id===plot.dataset.wellId),track=well.tracks.find(t=>t.id===plot.dataset.wbPlot);const depthAt=e=>{const r=plot.getBoundingClientRect(),range=visibleRange(well);return range[0]+Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))*(range[1]-range[0])+offsetFor(well);};plot.onclick=e=>{if(plot.dataset.justSelected==='1'){plot.dataset.justSelected='0';return;}const depth=depthAt(e);book().selected={wellId:well.id,trackId:track.id,curveId:track.curves[0]?.id};if(book().pickTop){pickTop(well,depth);return;}const values=track.curves.map(c=>{const source=cache.get(c.datasetId);if(!source)return '';const di=source.columns.findIndex(v=>v.id===c.indexColumnId),ci=source.columns.findIndex(v=>v.id===c.columnId),factor=depthFactor(sourceUnit(source.columns[di]));if(!factor)return '';let nearest=null,delta=Infinity;for(const row of source.rows){const observed=displayDepth(well,ds(c.datasetId),row[di]*factor,c),gap=observed===null?Infinity:Math.abs(observed-depth);if(gap<delta){nearest=row;delta=gap;}}return (ctx.host.getState().wellDrafts?.find(w=>w.id===well.wellId)?.name||well.wellId)+' Â· '+c.name+': '+(finite(nearest?.[ci])?Number(nearest[ci].toPrecision(6)):'null')+' '+(c.unit||'unit unresolved');}).filter(Boolean);board().cursor=depth.toFixed(3)+' m Â· '+values.join(' Â· ');board().focus='logs';ctx.host.save();redraw();};
 plot.onpointermove=e=>{const depth=depthAt(e)-offsetFor(well);for(const line of (plot.closest('[data-wb-pane]')||root).querySelectorAll('.wb-cursor-line')){const targetWell=book().wells.find(w=>w.id===line.closest('[data-well-id]').dataset.wellId),range=visibleRange(targetWell),y=(depth-range[0])/(range[1]-range[0])*620;line.setAttribute('y1',y);line.setAttribute('y2',y);}};
 plot.onwheel=e=>{if(!e.ctrlKey&&!e.metaKey&&!e.shiftKey)return;if(!wellExtent(well))return;e.preventDefault();if(e.shiftKey){const range=visibleRange(well),delta=(range[1]-range[0])*.15*Math.sign(e.deltaY);change('Pan depth',()=>{const next=[range[0]+delta,range[1]+delta];if(well.linked===false)well.range=next;else book().range=next;});}else zoom(e.deltaY>0?1.2:1/1.2,depthAt(e)-offsetFor(well),well);};
 plot.onpointerdown=e=>{const boundary=e.target.closest('[data-wb-zone-boundary]');if(boundary){e.preventDefault();e.stopPropagation();const zone=ctx.state().zones.find(z=>z.id===boundary.dataset.wbZoneBoundary),edge=boundary.dataset.edge,basis=well.basis&&well.basis!=='Source reference'?well.basis:sourceBasis(data().find(d=>d.well===well.wellId&&indexColumn(d))),originY=e.clientY;plot.setPointerCapture(e.pointerId);const move=event=>{const y=(depthAt(event)-offsetFor(well)-visibleRange(well)[0])/(visibleRange(well)[1]-visibleRange(well)[0])*620;boundary.setAttribute('y1',y);boundary.setAttribute('y2',y);},stop=()=>{plot.removeEventListener('pointermove',move);plot.removeEventListener('pointerup',finish);plot.removeEventListener('pointercancel',cancel);document.removeEventListener('keydown',escape);},cancel=()=>{stop();redraw();},escape=event=>{if(event.key==='Escape')cancel();},finish=event=>{stop();if(Math.abs(event.clientY-originY)<2){document.querySelector('.iw').dispatchEvent(new CustomEvent('pp-edit-zone',{detail:{zoneId:zone.id,edge}}));return;}const value=convertDepth(well,depthAt(event),basis,zone.reference),proposal={...zone,[edge]:value};if(!finite(value)||proposal.base<=proposal.top||(ctx.state().zones||[]).some(z=>z.id!==zone.id&&z.wellId===zone.wellId&&z.reference===zone.reference&&z.top<proposal.base&&z.base>proposal.top)){fail(new Error('Zone boundaries must remain ordered and cannot overlap another zone.'));redraw();return;}change('Edit zone boundary',()=>{zone[edge]=value;for(const w of ctx.state().windows){w.stale=true;delete w.runId;for(const binding of Object.values(w.bindings||{}))binding.confirmed=false;}});};plot.addEventListener('pointermove',move);plot.addEventListener('pointerup',finish);plot.addEventListener('pointercancel',cancel);document.addEventListener('keydown',escape);return;}if(!e.shiftKey)return;e.preventDefault();const top=depthAt(e);plot.setPointerCapture(e.pointerId);const finish=ev=>{plot.removeEventListener('pointerup',finish);plot.dataset.justSelected='1';const base=depthAt(ev);if(Math.abs(base-top)>.0001)change('Select depth interval',()=>{book().selectionRange={top:Math.min(top,base),base:Math.max(top,base)};book().brush=null;book().selected={wellId:well.id,trackId:track.id,curveId:track.curves[0]?.id};});};plot.addEventListener('pointerup',finish);};
 plot.onkeydown=e=>{if(['+','=','-'].includes(e.key)){e.preventDefault();zoom(e.key==='-'?2:.5,null,well);}if(e.key==='Enter')select(well,track,track.curves[0]);};});}
function bindCrossplot(){
 const svg=$('#wb-crossplot-svg');
 if(!svg)return;
 svg.onpointerdown=event=>{
  const transform=svg.getScreenCTM();
  if(event.button!==0||!event.isPrimary||!transform)return;
  event.preventDefault();
  const inverse=transform.inverse();
  const point=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(inverse);
  const start=point(event),sample=event.target.closest('[data-wb-sample-row]')?.dataset.wbSampleRow;
  const rect=$('#wb-brush-rect');
  const move=e=>{
   const end=point(e);
   rect.setAttribute('x',Math.min(start.x,end.x));
   rect.setAttribute('y',Math.min(start.y,end.y));
   rect.setAttribute('width',Math.abs(start.x-end.x));
   rect.setAttribute('height',Math.abs(start.y-end.y));
  };
  const stop=()=>{
   svg.removeEventListener('pointermove',move);
   svg.removeEventListener('pointerup',finish);
   svg.removeEventListener('lostpointercapture',stop);
   document.removeEventListener('keydown',cancel);
   rect.setAttribute('width',0);
   if(svg.hasPointerCapture(event.pointerId))svg.releasePointerCapture(event.pointerId);
  };
  const cancel=e=>{if(e.key==='Escape')stop();};
  const finish=e=>{
   stop();
   const end=point(e),xmin=Number(svg.dataset.xmin),xmax=Number(svg.dataset.xmax);
   const ymin=Number(svg.dataset.ymin),ymax=Number(svg.dataset.ymax);
   const x=v=>xmin+(v-45)/525*(xmax-xmin),y=v=>ymin+(260-v)/240*(ymax-ymin);
   if(Math.hypot(end.x-start.x,end.y-start.y)<3){
    if(sample!==undefined)change('Select crossplot sample',()=>{book().brush={...book().crossplot,row:Number(sample)};book().selectionRange=null;});
    return;
   }
   change('Brush crossplot samples',()=>{
    book().brush={...book().crossplot,xmin:Math.min(x(start.x),x(end.x)),xmax:Math.max(x(start.x),x(end.x)),ymin:Math.min(y(start.y),y(end.y)),ymax:Math.max(y(start.y),y(end.y))};
    book().selectionRange=null;
   });
  };
  svg.setPointerCapture(event.pointerId);
  svg.addEventListener('pointermove',move);
  svg.addEventListener('pointerup',finish);
  svg.addEventListener('lostpointercapture',stop);
  document.addEventListener('keydown',cancel);
 };
}

function displayResultCurves(runId,datasets){
 const b=board();for(const dataset of datasets){const index=indexColumn(dataset);for(const column of numericColumns(dataset).filter(c=>c.id!==index?.id)){
  if(b.books.some(book=>book.wells.some(w=>w.tracks.some(t=>t.curves.some(c=>c.datasetId===dataset.id&&c.columnId===column.id)))))continue;
  let target=book(),well=target.wells.find(w=>w.wellId===dataset.well);
  if(well?.tracks.length>=30||!well&&target.wells.length>=30){target=freshBook('Result comparison · '+runId.slice(-8)+' · '+(b.books.length+1));b.books.push(target);b.activeBook=target.id;well=null;}
  well||=addWell(target,dataset.well||'Calculated evidence',[]);addCurve(well,dataset,column.id);
 }}b.focus='logs';
}
export function addAcceptedResults(runId){const accepted=data().filter(d=>d.scientificRunId===runId&&!d.isProposal&&indexColumn(d));if(!accepted.length)return;change('Add accepted calculated curves',()=>{ctx.state().proposals=(ctx.state().proposals||[]).filter(d=>d.scientificRunId!==runId);displayResultCurves(runId,accepted);});}
export function showProposal(runId,result){if(result.reviewState==='accepted'&&!result.stale)return addAcceptedResults(runId);const indexed=result.datasets.filter(d=>d.indexColumnId&&numericColumns(d).some(c=>c.id!==d.indexColumnId));if(!indexed.length)throw new Error('This result has no reviewed scalar depth curves. Use its table/array view; no log depth will be invented.');change('Preview full indexed proposal',()=>{ctx.state().proposals||=[];for(const d of indexed){const {preview,...manifest}=d;const entry={...structuredClone(manifest),family:'derived',isProposal:true,scientificRunId:runId,status:(result.reviewState==='rejected'?'Rejected · comparison only':result.reviewState==='accepted'?'Accepted · comparison only':'Proposed · not accepted')+(result.stale?' · stale source evidence':''),reviewable:!result.stale&&(!result.reviewState||result.reviewState==='completed')};ctx.state().proposals=ctx.state().proposals.filter(p=>p.id!==d.id);ctx.state().proposals.push(entry);}displayResultCurves(runId,indexed);});}
